const e={1:{dayName:"Dia 1 — Segunda-feira",title:"Verbo To Be (Afirmativa) & Apresentação Pessoal",focus:"Aprender a se apresentar em inglês e usar o Verbo To Be no presente.",vocab:[{en:"Hello",pt:"Olá"},{en:"Good morning",pt:"Bom dia"},{en:"My name is...",pt:"Meu nome é..."},{en:"I am...",pt:"Eu sou / Eu estou..."},{en:"Student",pt:"Estudante"},{en:"Teacher",pt:"Professor(a)"},{en:"Computer",pt:"Computador"},{en:"Code",pt:"Código / Programar"},{en:"File",pt:"Arquivo"},{en:"Yes / No",pt:"Sim / Não"}],grammar:{title:"Verbo To Be (Afirmativa)",rule:"O verbo To Be significa SER ou ESTAR. No presente ele assume 3 formas: AM, IS, ARE.",table:[{form:"I am (I'm)",example:"I am a student.",pt:"Eu sou um estudante."},{form:"You are (You're)",example:"You are smart.",pt:"Você é inteligente."},{form:"He is (He's)",example:"He is a developer.",pt:"Ele é um desenvolvedor."},{form:"She is (She's)",example:"She is at home.",pt:"Ela está em casa."},{form:"It is (It's)",example:"It is a computer.",pt:"É um computador."},{form:"We are (We're)",example:"We are ready.",pt:"Nós estamos prontos."},{form:"They are (They're)",example:"They are happy.",pt:"Eles são felizes."}],foundation:{title:"Como escolher AM, IS ou ARE",explanation:"Em inglês, a frase precisa mostrar quem é o sujeito e qual forma do verbo combina com ele. Não escolha pelo significado em português: escolha pela pessoa da frase.",steps:["I usa sempre AM → I am.","He, she e it usam IS → She is.","You, we e they usam ARE → They are.","Ordem da frase: sujeito + To Be + informação → I am a student."],warning:"Não diga 'I is' ou 'she are'. Aprenda o par inteiro: I am, she is, they are."}},reading:{title:"My First Day",text:"Hello! My name is Ruan. I am a student. I live in Brazil. I have a computer. The computer is on the table. I am happy today.",translation:"Olá! Meu nome é Ruan. Eu sou um estudante. Eu moro no Brasil. Eu tenho um computador. O computador está sobre a mesa. Eu estou feliz hoje."},quiz:[{q:"Complete: 'I ___ a student.'",options:["am","is","are"],ans:"am"},{q:"Complete: 'She ___ a developer.'",options:["am","is","are"],ans:"is"},{q:"Complete: 'The computers ___ new.'",options:["am","is","are"],ans:"are"}],chunks:[{en:"I am a student.",pt:"Eu sou um estudante."},{en:"I live in Brazil.",pt:"Eu moro no Brasil."},{en:"I am happy to learn.",pt:"Estou feliz em aprender."}],listeningScript:"Hello! My name is John. I am a software engineer. I live in New York. My computer is fast. I love programming.",speakingPrompt:"Fale em voz alta: 'Hello! My name is Ruan. I am a student. I live in Brazil. I study English and Computer Science.'",lightReading:"Computers are electronic devices that process data according to instructions.",journalPrompt:"Today is Day 1. I studied the verb to be. I am happy to start.",tip:"DICA DE LEITURA: você já conhece muitas palavras em inglês sem saber. Cognatos iguais em português: computer, internet, program, system, file, code. Ao ler, sublinhe primeiro as palavras que 'parecem' português."},2:{dayName:"Dia 2 — Terça-feira",title:"Verbo To Be (Negativa & Perguntas)",focus:"Aprender a negar (isn't, aren't) e fazer perguntas cotidianas.",vocab:[{en:"Not",pt:"Não"},{en:"Tired",pt:"Cansado(a)"},{en:"Busy",pt:"Ocupado(a)"},{en:"Ready",pt:"Pronto(a)"},{en:"Where",pt:"Onde"},{en:"Who",pt:"Quem"},{en:"What",pt:"O que / Qual"},{en:"Office",pt:"Escritório"},{en:"Home",pt:"Casa / Lar"},{en:"Work",pt:"Trabalho"}],grammar:{title:"Verbo To Be (Negativa & Perguntas)",rule:"Negativa: mantenha a ordem normal e adicione NOT depois de AM/IS/ARE. Perguntas de sim/não: AM/IS/ARE vem antes da pessoa. Com WHAT/WHERE/WHO, a palavra de pergunta vem primeiro e o verbo To Be continua antes da pessoa.",table:[{form:"Afirmação (ordem normal)",example:"You are ready.",pt:"Você está pronto."},{form:"Negativa (NOT depois do verbo)",example:"You are not ready. / You aren't ready.",pt:"Você não está pronto."},{form:"Pergunta sim/não (verbo primeiro)",example:"Are you ready?",pt:"Você está pronto?"},{form:"Pergunta com informação",example:"Where are you? / Who is she?",pt:"Onde você está? / Quem é ela?"},{form:"Resposta curta",example:"Yes, I am. / No, she isn't.",pt:"Sim, estou. / Não, ela não está."}],foundation:{title:"Por que 'You are' vira 'Are you?'",explanation:"Em português, muitas perguntas mantêm a mesma ordem: 'Você está pronto?' Em inglês, o verbo To Be mostra que é pergunta ao passar para a frente. Pense como uma troca de posições: YOU ARE → ARE YOU? Não traduza palavra por palavra; reconheça o molde.",steps:["Frase normal: sujeito + To Be + complemento → You are ready.","Para negar: sujeito + To Be + NOT + complemento → You are not ready.","Para perguntar: To Be + sujeito + complemento? → Are you ready?","Se houver uma pergunta como WHERE, ela entra antes: Where are you?"],warning:"Erro comum: 'You are ready?' pode aparecer numa conversa informal para confirmar algo, mas no inglês padrão que você deve aprender e usar em entrevistas, diga 'Are you ready?'"}},reading:{title:"At the Office",text:"Is Paul at work today? No, he is not. He is at home. He is sick. But Maria is in the office. She is not sick. She is very busy.",translation:"O Paul está no trabalho hoje? Não, ele não está. Ele está em casa. Ele está doente. Mas a Maria está no escritório. Ela não está doente. Ela está muito ocupada."},quiz:[{q:"Negativa de 'He is busy':",options:["He not is busy","He isn't busy","He don't busy"],ans:"He isn't busy"},{q:"Pergunta correta:",options:["You are ready?","Are you ready?","Is you ready?"],ans:"Are you ready?"},{q:"Complete: '___ you at home?'",options:["Are","You are","Is"],ans:"Are"},{q:"Resposta curta de 'Are you a student?':",options:["Yes, I am.","Yes, you are.","No, it isn't."],ans:"Yes, I am."}],chunks:[{en:"I am not tired.",pt:"Eu não estou cansado."},{en:"Are you ready?",pt:"Você está pronto?"},{en:"No, it is not online.",pt:"Não, não está online."}],speakingTargets:["Yes, I am.","No, I am not tired.","Are you ready?","No, it is not online."],listeningScript:"Is the server online? No, it is offline right now. Are we ready for the team meeting? Yes, we are ready.",speakingPrompt:"Responda oralmente: 'Are you a student? Yes, I am. Are you tired today? No, I am not tired.'",lightReading:"Software is not physical hardware. It consists of logical code instructions.",journalPrompt:"Today is Day 2. I learned negative sentences and short answers in English.",tip:"DICA DE ESCRITA: toda frase em inglês precisa de SUJEITO + VERBO. Pegue o hábito de escrever frases completas no caderno. Escreva também sua rotina: 'I am a student. I am at home in the evening.'"},3:{dayName:"Dia 3 — Quarta-feira",title:"Pronome IT & Hardware de Computadores",focus:"Usar o pronome IT para objetos e aprender nomes de peças de computador.",vocab:[{en:"Keyboard",pt:"Teclado"},{en:"Mouse",pt:"Mouse"},{en:"Screen",pt:"Tela / Monitor"},{en:"Memory",pt:"Memória"},{en:"Processor",pt:"Processador"},{en:"Fast",pt:"Rápido(a)"},{en:"Slow",pt:"Lento(a)"},{en:"New",pt:"Novo(a)"},{en:"Old",pt:"Velho(a)"},{en:"System",pt:"Sistema"}],grammar:{title:"Uso de IT e THEY para Objetos",rule:"Usamos IT para objetos no singular. No plural usamos THEY.",table:[{form:"Singular (IT)",example:"The computer is fast. -> It is fast.",pt:"O computador é rápido. Ele é rápido."},{form:"Plural (THEY)",example:"The screens are new. -> They are new.",pt:"As telas são novas. Elas são novas."}],foundation:{title:"Pronome substitui o nome",explanation:"Depois de citar um nome, você pode substituí-lo por um pronome para não repetir a palavra. O pronome precisa combinar com quantidade: uma coisa ou várias coisas.",steps:["Uma coisa/objeto: computer → it.","Várias coisas/objetos: computers → they.","O verbo acompanha o pronome: it is, they are."],warning:"Para objetos, não use he ou she na base do inglês: use it no singular e they no plural."}},reading:{title:"My New Laptop",text:"I have a new laptop. It is very fast. The screen is big and clear. The keyboard is quiet. My old computer was slow, but this laptop is great for programming.",translation:"Eu tenho um notebook novo. Ele é muito rápido. A tela é grande e clara. O teclado é silencioso. Meu computador antigo era lento, mas este notebook é ótimo para programação."},quiz:[{q:"Substitua 'The keyboard' por pronome:",options:["He","She","It"],ans:"It"},{q:"Substitua 'The servers' por pronome:",options:["It","They","We"],ans:"They"},{q:"'Screen' significa:",options:["Teclado","Tela","Mouse"],ans:"Tela"}],chunks:[{en:"It is very fast.",pt:"Ele é muito rápido."},{en:"The screen is big.",pt:"A tela é grande."},{en:"They are online.",pt:"Eles estão online."}],listeningScript:"My laptop is brand new. It has sixteen gigabytes of RAM. The CPU is fast. It is perfect for software engineering.",speakingPrompt:"Descreva seu computador: 'My computer is [fast/slow]. The screen is [big/small]. It has good memory.'",lightReading:"A central processing unit (CPU) carries out instructions of a computer program.",journalPrompt:"Today is Day 3. I learned how to describe my computer in English.",tip:"DICA DE PRONÚNCIA: ouça e repita em voz alta 3 vezes cada palavra nova. A voz do app ajuda: clique no alto-falante e imite o ritmo e a entonação, não a tradução."},4:{dayName:"Dia 4 — Quinta-feira",title:"Artigos A, AN & THE (Singular & Plural)",focus:"Dominar quando usar A (consoante), AN (vogal) e THE (específico).",vocab:[{en:"A / An",pt:"Um / Uma"},{en:"The",pt:"O / A / Os / As"},{en:"Application",pt:"Aplicativo"},{en:"Engineer",pt:"Engenheiro(a)"},{en:"Developer",pt:"Desenvolvedor(a)"},{en:"User",pt:"Usuário(a)"},{en:"Error",pt:"Erro"},{en:"Algorithm",pt:"Algoritmo"},{en:"Database",pt:"Banco de dados"},{en:"Project",pt:"Projeto"}],grammar:{title:"Regra dos Artigos A, AN e THE",rule:"Usamos A antes de som de consoante (a computer). Usamos AN antes de som de vogal (an app). Usamos THE para especificar (the server).",table:[{form:"A (Consoante)",example:"a developer, a system",pt:"um desenvolvedor, um sistema"},{form:"AN (Vogal)",example:"an application, an engineer, an error",pt:"um aplicativo, um engenheiro, um erro"},{form:"THE (Específico)",example:"The database is online.",pt:"O banco de dados está online."}],foundation:{title:"Primeira menção vs. coisa específica",explanation:"A/AN apresenta uma coisa qualquer; THE aponta para uma coisa que já sabemos qual é. A escolha entre A e AN depende do som inicial, não apenas da primeira letra.",steps:["Primeira vez: I use an app. (um aplicativo qualquer)","Agora já sabemos qual: The app is fast. (aquele aplicativo)","Som de consoante: a user. Som de vogal: an error."],warning:"Não tente traduzir sempre A/AN como 'um'. A função é apresentar algo não específico."}},reading:{title:"An Engineer at Work",text:"Alex is an engineer. He works at a software company. Today he found an error in an application. He fixed the error. The application is now working perfectly.",translation:"Alex é um engenheiro. Ele trabalha em uma empresa de software. Hoje ele encontrou um erro em um aplicativo. Ele corrigiu o erro. O aplicativo agora está funcionando perfeitamente."},quiz:[{q:"Complete: 'She is ___ engineer.'",options:["a","an","the"],ans:"an"},{q:"Complete: 'I use ___ computer.'",options:["a","an","the"],ans:"a"},{q:"Complete: '___ algorithm is a step-by-step procedure.'",options:["A","An","The"],ans:"An"}],chunks:[{en:"an application",pt:"um aplicativo"},{en:"a software engineer",pt:"um engenheiro de software"},{en:"fix the error",pt:"corrigir o erro"}],listeningScript:"An engineer designs systems. A developer writes code. The code must be clean, safe, and efficient.",speakingPrompt:"Diga 3 frases com A, AN e THE: 'I am a student. I use an app. The app is fast.'",lightReading:"An algorithm is a step-by-step procedure designed to perform a specific task.",journalPrompt:"Today is Day 4. I mastered the articles A, AN and THE.",tip:"DICA DE ESCRITA: artigos definem se falamos de algo geral ou específico. 'I want an app' (qualquer app) vs 'I want the app' (esse app específico). Preste atenção nisso ao ler textos."},5:{dayName:"Dia 5 — Sexta-feira",title:"Demonstrativos (This, That, These, Those)",focus:"Saber apontar coisas perto e longe no singular e no plural.",vocab:[{en:"This",pt:"Este (perto, singular)"},{en:"That",pt:"Aquele (longe, singular)"},{en:"These",pt:"Estes (perto, plural)"},{en:"Those",pt:"Aqueles (longe, plural)"},{en:"Here",pt:"Aqui"},{en:"There",pt:"Lá"},{en:"Desk",pt:"Mesa de trabalho"},{en:"Folder",pt:"Pasta de arquivos"},{en:"Line of code",pt:"Linha de código"},{en:"Document",pt:"Documento"}],grammar:{title:"Demonstrativos Perto vs Longe",rule:"Perto: THIS (singular) e THESE (plural). Longe: THAT (singular) e THOSE (plural).",table:[{form:"This (perto, 1)",example:"This is my computer.",pt:"Este é o meu computador."},{form:"That (longe, 1)",example:"That is a server.",pt:"Aquele é um servidor."},{form:"These (perto, +1)",example:"These are my files.",pt:"Estes são os meus arquivos."},{form:"Those (longe, +1)",example:"Those are old systems.",pt:"Aqueles são sistemas antigos."}]},reading:{title:"Organizing the Desk",text:"Look at this computer on my desk. This is my main workspace. These files here are new projects. Those documents on that shelf are old. I need to organize them today.",translation:"Olhe para este computador na minha mesa. Esta é minha área de trabalho principal. Estes arquivos aqui são projetos novos. Aqueles documentos naquela prateleira são antigos. Preciso organizá-los hoje."},quiz:[{q:"Objeto perto no singular:",options:["This","That","These"],ans:"This"},{q:"Vários objetos longe:",options:["These","Those","This"],ans:"Those"},{q:"'These' é usado para:",options:["1 objeto longe","vários objetos perto","1 objeto perto"],ans:"vários objetos perto"}],chunks:[{en:"This is my code.",pt:"Este é o meu código."},{en:"These are new features.",pt:"Estas são novas funcionalidades."},{en:"That is an old server.",pt:"Aquele é um servidor antigo."}],listeningScript:"This is line 10 of the program. These variables hold data. That function computes the result.",speakingPrompt:"Aponte para objetos ao seu redor: 'This is my phone. These are my books. That is the door.'",lightReading:"These data structures hold memory elements. Those functions operate on them.",journalPrompt:"Today is Day 5. I learned how to use This, That, These and Those.",tip:"DICA DE LEITURA: ao ler, pergunte-se 'quem? o quê? onde?' — who, what, where. Essas perguntas guiam sua compreensão de qualquer texto curto."},6:{dayName:"Dia 6 — Sábado",title:"Possessivos (My, Your, His, Her, Our, Their) & TESTE DE SÁBADO",focus:"Indicar posse e realizar a avaliação semanal da Semana 1.",vocab:[{en:"My",pt:"Meu / Minha"},{en:"Your",pt:"Seu / Sua"},{en:"His",pt:"Dele"},{en:"Her",pt:"Dela"},{en:"Our",pt:"Nosso(a)"},{en:"Their",pt:"Deles / Delas"},{en:"Team",pt:"Equipe"},{en:"Company",pt:"Empresa"},{en:"Skill",pt:"Habilidade"},{en:"Goal",pt:"Meta"}],grammar:{title:"Possessivos em Inglês",rule:"Usamos os adjetivos possessivos antes de nomes: My computer, His code, Her app, Our team.",table:[{form:"I -> My",example:"My project is ready.",pt:"Meu projeto está pronto."},{form:"He -> His",example:"His code is clean.",pt:"O código dele é limpo."},{form:"She -> Her",example:"Her app is live.",pt:"O app dela está no ar."},{form:"We -> Our",example:"Our team is great.",pt:"Nossa equipe é ótima."}]},reading:{title:"Our Software Team",text:"We work in a software company. Our team has four developers. Maria is our team leader. Her coding skills are amazing. Lucas is a frontend dev. His code is very neat.",translation:"Nós trabalhamos em uma empresa de software. Nossa equipe tem quatro desenvolvedores. Maria é nossa líder de equipe. As habilidades de código dela são incríveis. Lucas é um dev frontend. O código dele é muito organizado."},quiz:[{q:"'John and ___ laptop' (notebook dele):",options:["his","her","their"],ans:"his"},{q:"'We love ___ studies' (nossos estudos):",options:["my","our","their"],ans:"our"},{q:"'Maria é líder. ___ skills são incríveis.':",options:["His","Her","Their"],ans:"Her"}],chunks:[{en:"our dev team",pt:"nossa equipe de desenvolvimento"},{en:"his code is clean",pt:"o código dele é limpo"},{en:"her app is live",pt:"o app dela está no ar"}],listeningScript:"Welcome to our engineering department. My name is Mark. This is our team. Their project is an AI system.",speakingPrompt:"Grave seu áudio de 2 minutos na aba 'Teste dos Sábados' falando sobre sua semana!",lightReading:"Our repositories are stored on GitHub. Their access is protected by tokens.",journalPrompt:"Today is Day 6. I finished my Saturday Test Protocol!",tip:"DICA DE MEMÓRIA: revise SEMPRE no mesmo dia. O cérebro esquece rápido; revisar a lista do dia antes de dormir fixa 3x mais."},7:{dayName:"Dia 7 — Domingo",title:"Revisão Geral da Semana 1 & Imersão Leve",focus:"Consolidar a Semana 1 com revisão ativa de tudo que foi estudado.",vocab:[{en:"Review",pt:"Revisão"},{en:"Week",pt:"Semana"},{en:"Foundation",pt:"Fundação"},{en:"Confidence",pt:"Confiança"},{en:"Achievement",pt:"Conquista"},{en:"Rest",pt:"Descanso"},{en:"Movie",pt:"Filme"},{en:"Podcast",pt:"Podcast"},{en:"Success",pt:"Sucesso"},{en:"Progress",pt:"Progresso"}],grammar:{title:"Resumo Completo da Semana 1",rule:"Você concluiu 7 dias de imersão! Dominou To Be, Artigos (A, An, The), Demonstrativos e Possessivos.",table:[{form:"To Be",example:"I am a student. Are you ready?",pt:"Sou estudante. Você está pronto?"},{form:"Objetos & Possessivos",example:"This is my laptop. Our code is clean.",pt:"Este é meu notebook. Nosso código é limpo."},{form:"Artigos",example:"An engineer found an error in the system.",pt:"Um engenheiro encontrou um erro no sistema."}]},reading:{title:"Seven Days Complete!",text:"Today is the seventh day of my English immersion. I studied every single day for hours. I know the verb To Be, articles, pronouns, and technical words. I am confident and ready for Week 2!",translation:"Hoje é o sétimo dia da minha imersão em inglês. Eu estudei todos os dias. Eu sei o verbo To Be, artigos, pronomes e palavras técnicas. Estou confiante e pronto para a Semana 2!"},quiz:[{q:"Frase correta:",options:["I am ready","I is ready","I be ready"],ans:"I am ready"},{q:"Artigo correto:",options:["an algorithm","a algorithm","the algorithm error"],ans:"an algorithm"},{q:"Correto:",options:["This are my files","These are my files","This is my files"],ans:"These are my files"}],chunks:[{en:"Week 1 is complete!",pt:"A Semana 1 está completa!"},{en:"I am ready for Week 2.",pt:"Estou pronto para a Semana 2."},{en:"My progress is awesome.",pt:"Meu progresso é incrível."}],listeningScript:"Congratulations! You completed week one of your English immersion journey. You have built a solid foundation.",speakingPrompt:"Fale em voz alta: 'I finished week 1. I am proud of my dedication. Next week will be even better!'",lightReading:"Relax and watch a video in English with English subtitles today.",journalPrompt:"Today is Day 7. I completed my first intensive week. I am happy and proud!",tip:"DICA DE APRENDIZADO: domingo é dia de input leve. Assista, leia ou ouça algo em inglês sem obrigação. Seu cérebro aprende até 'só ouvindo' quando já estudou o conteúdo antes."},8:{dayName:"Dia 8 — Segunda-feira",title:"Artigos A/AN: Som, Não Letra!",focus:"Entender que A e AN dependem do SOM da palavra, não da letra escrita.",vocab:[{en:"Hour",pt:"Hora"},{en:"University",pt:"Universidade"},{en:"Router",pt:"Roteador"},{en:"Email",pt:"E-mail"},{en:"Interview",pt:"Entrevista"},{en:"App",pt:"Aplicativo"},{en:"Laptop",pt:"Notebook"},{en:"Update",pt:"Atualização"},{en:"Button",pt:"Botão"},{en:"Website",pt:"Site"}],grammar:{title:"A vs AN — Pelo Som",rule:"AN antes de som de vogal (an app, an hour); A antes de som de consoante (a university, a user). 'University' começa com som de Y (consoante), e 'hour' tem H mudo (som de vogal).",table:[{form:"An + som vogal",example:"an hour, an error, an application",pt:"uma hora, um erro, um aplicativo"},{form:"A + som consoante",example:"a university, a user, a router",pt:"uma universidade, um usuário, um roteador"},{form:"Atenção",example:"an hour (H mudo) / a house (H falado)",pt:"uma hora / uma casa"}]},reading:{title:"My First Email",text:"I sent an email this morning. It was an important email. I wrote to a user who had an error with the app. I answered in an hour. I am happy because the user is satisfied now.",translation:"Enviei um e-mail esta manhã. Era um e-mail importante. Escrevi para um usuário que tinha um erro no app. Respondi em uma hora. Estou feliz porque o usuário está satisfeito agora."},quiz:[{q:"Complete: '___ hour'",options:["A","An","The"],ans:"An"},{q:"Complete: '___ university'",options:["A","An","The"],ans:"A"},{q:"Complete: '___ update' (atualização)",options:["A","An","The"],ans:"An"}],chunks:[{en:"an hour",pt:"uma hora"},{en:"an error in the app",pt:"um erro no aplicativo"},{en:"a new update",pt:"uma atualização nova"}],listeningScript:"I received an email today. It was from a user. He found an error in the application. I fixed it in an hour. It was a quick update.",speakingPrompt:"Diga: 'This is an app. This is a website. I answered in an hour.'",lightReading:"A router is a device that sends data between computers in a network.",journalPrompt:"Today is Day 8. I learned that A and AN depend on the sound.",tip:"DICA DE LEITURA/PRONÚNCIA: o inglês se lê pelo SOM, não pela letra. H no início de 'hour' é mudo. Sempre ouça a palavra com o áudio antes de decidi-la — som manda em inglês."},9:{dayName:"Dia 9 — Terça-feira",title:"THE & Omissão do Artigo",focus:"Saber usar THE (específico) e quando NÃO usar artigo.",vocab:[{en:"Internet",pt:"Internet"},{en:"Language",pt:"Idioma / Língua"},{en:"Lunch",pt:"Almoço"},{en:"Breakfast",pt:"Café da manhã"},{en:"Education",pt:"Educação"},{en:"Company",pt:"Empresa"},{en:"Market",pt:"Mercado"},{en:"Industry",pt:"Indústria"},{en:"Software",pt:"Software"},{en:"Hardware",pt:"Hardware"}],grammar:{title:"THE e Zero Article",rule:"THE para algo específico ou único (the internet, the CEO of the company). Sem artigo: idiomas, refeições, plurais gerais e áreas de estudo (English, lunch, computers are useful).",table:[{form:"THE (específico)",example:"The internet is fast today.",pt:"A internet está rápida hoje."},{form:"Sem artigo (geral)",example:"English is important for developers.",pt:"O inglês é importante para desenvolvedores."},{form:"Sem artigo (plural geral)",example:"Computers are everywhere.",pt:"Computadores estão em todo lugar."}]},reading:{title:"Languages and Technology",text:"The internet connects people all over the world. English is the main language of technology. Developers read documentation in English. Lunch at our company is at twelve. We talk about the industry every day.",translation:"A internet conecta pessoas em todo o mundo. O inglês é o principal idioma da tecnologia. Desenvolvedores leem documentação em inglês. O almoço na nossa empresa é ao meio-dia. Falamos sobre a indústria todos os dias."},quiz:[{q:"Qual tem THE?",options:["___ internet","___ breakfast","___ languages"],ans:"The internet"},{q:"Qual NÃO leva artigo?",options:["___ CEO of our company","___ English is easy","___ error in the code"],ans:"English is easy"},{q:"Complete: 'Computers ___ useful.'",options:["is","are","am"],ans:"are"}],chunks:[{en:"the internet",pt:"a internet"},{en:"the main language",pt:"o idioma principal"},{en:"developers read documentation",pt:"desenvolvedores leem documentação"}],listeningScript:"English is the language of software. The documentation is usually in English. The developers read it every morning. At lunch, they discuss the newest technology.",speakingPrompt:"Diga: 'English is important. The internet is amazing. Computers are everywhere.'",lightReading:"Software companies operate in a global market, and English is the working language of that market.",journalPrompt:"Today is Day 9. I learned when to use THE and when to use no article.",tip:"DICA DE LEITURA: leia em blocos de 3 a 5 palavras, não palavra por palavra. 'The main language / of technology' — seu cérebro entende o sentido do grupo, e isso acelera sua velocidade de leitura."},10:{dayName:"Dia 10 — Quarta-feira",title:"Plurais Regulares (-s, -es, -ies)",focus:"Formar plurais dos substantivos regulares com as regras de terminação.",vocab:[{en:"Box",pt:"Caixa"},{en:"Boxes",pt:"Caixas"},{en:"Class",pt:"Aula / Classe"},{en:"Classes",pt:"Aulas"},{en:"City",pt:"Cidade"},{en:"Cities",pt:"Cidades"},{en:"Country",pt:"País"},{en:"Countries",pt:"Países"},{en:"Name",pt:"Nome"},{en:"Names",pt:"Nomes"}],grammar:{title:"Plurais Regulares",rule:"Geral: +s (file -> files). Depois de ch, sh, s, x: +es (box -> boxes). Consoante + y: -y -> -ies (city -> cities).",table:[{form:"+s",example:"file -> files, name -> names",pt:"arquivo -> arquivos, nome -> nomes"},{form:"+es (ch, sh, s, x)",example:"box -> boxes, class -> classes",pt:"caixa -> caixas, aula -> aulas"},{form:"-y -> -ies",example:"city -> cities, country -> countries",pt:"cidade -> cidades, país -> países"}]},reading:{title:"Files and Folders",text:"I have many files on my computer. Some files are documents. Some are images. I organize them in folders. Cities have many users of computers too. In our office, we manage hundreds of files every day.",translation:"Eu tenho muitos arquivos no meu computador. Alguns arquivos são documentos. Alguns são imagens. Eu os organizo em pastas. As cidades também têm muitos usuários de computadores. No nosso escritório, gerenciamos centenas de arquivos todos os dias."},quiz:[{q:"Plural de 'box':",options:["boxs","boxes","boxies"],ans:"boxes"},{q:"Plural de 'city':",options:["citys","cities","citiyes"],ans:"cities"},{q:"Plural de 'file':",options:["files","filees","fily"],ans:"files"}],chunks:[{en:"many files",pt:"muitos arquivos"},{en:"hundreds of users",pt:"centenas de usuários"},{en:"organize them in folders",pt:"organizá-los em pastas"}],listeningScript:"In my company, we work with many files. Some files are code. Some are documents. We put them in folders. The folders are organized by projects and by cities.",speakingPrompt:"Fale no plural: 'I have files, boxes, and documents. Cities have internet. Classes start at nine.'",lightReading:"Folders group files together so users can find and manage them easily.",journalPrompt:"Today is Day 10. I learned regular plurals in English.",tip:"DICA DE ESCRITA: plural em inglês quase nunca muda o contexto do verbo ('files ARE', não 'files is'). Ao escrever, combine o plural com o verbo correto — isso é o que mais entrega um nível A2."},11:{dayName:"Dia 11 — Quinta-feira",title:"Plurais Irregulares & Pessoas",focus:"Memorizar os plurais irregulares mais comuns usados no dia a dia e no trabalho.",vocab:[{en:"Man",pt:"Homem"},{en:"Men",pt:"Homens"},{en:"Woman",pt:"Mulher"},{en:"Women",pt:"Mulheres"},{en:"Child",pt:"Criança"},{en:"Children",pt:"Crianças"},{en:"Person",pt:"Pessoa"},{en:"People",pt:"Pessoas"},{en:"Mouse",pt:"Mouse"},{en:"Mice",pt:"Mouses (animais)"}],grammar:{title:"Plurais Irregulares",rule:"Alguns plurais mudam a palavra inteira: man -> men, woman -> women, child -> children, person -> people, mouse -> mice.",table:[{form:"man -> men",example:"One man, two men.",pt:"Um homem, dois homens."},{form:"woman -> women",example:"She is a woman. They are women.",pt:"Ela é uma mulher. Elas são mulheres."},{form:"person -> people",example:"Many people use this software.",pt:"Muitas pessoas usam este software."}]},reading:{title:"People in Our Office",text:"There are many people in our office. One man is the manager. Two women work in marketing. A child visits the office on Friday. The children like the robots. Our team has good people.",translation:"Há muitas pessoas no nosso escritório. Um homem é o gerente. Duas mulheres trabalham em marketing. Uma criança visita o escritório na sexta-feira. As crianças gostam dos robôs. Nossa equipe tem boas pessoas."},quiz:[{q:"Plural de 'man':",options:["mans","men","mens"],ans:"men"},{q:"Plural de 'person':",options:["persons","peoples","people"],ans:"people"},{q:"Plural de 'child':",options:["childs","children","childes"],ans:"children"}],chunks:[{en:"many people",pt:"muitas pessoas"},{en:"the manager",pt:"o gerente"},{en:"good people",pt:"boas pessoas"}],listeningScript:"Our team is small but great. There are three men and two women. People like working here. The manager is a friendly man. Children visit and play with the robots.",speakingPrompt:"Conte as pessoas ao seu redor: 'There is one man. There are two women. There are many people in this city.'",lightReading:"The word 'people' is already plural; we never say 'peoples' for a group of humans.",journalPrompt:"Today is Day 11. I learned irregular plurals: men, women, children, people.",tip:"DICA DE MEMÓRIA: agrupe palavras irregulares em 'famílias'. People/children/men/women = grupo irregular de pessoas. Descobrir famílias torna a memorização muito mais rápida."},12:{dayName:"Dia 12 — Sexta-feira",title:"Demonstrativos com Distância + ONE/ONES",focus:"Usar this/that/these/those com distância e substituir nomes com one/ones.",vocab:[{en:"Near",pt:"Perto"},{en:"Far",pt:"Longe"},{en:"Shelf",pt:"Prateleira"},{en:"Server",pt:"Servidor"},{en:"Room",pt:"Sala"},{en:"Window",pt:"Janela"},{en:"Wall",pt:"Parede"},{en:"Table",pt:"Mesa"},{en:"Chair",pt:"Cadeira"},{en:"Light",pt:"Luz"}],grammar:{title:"This/That/These/Those + One/Ones",rule:"Perto = this/these. Longe = that/those. ONE e ONES substituem o substantivo para evitar repetição: 'This laptop is new. That one is old.'",table:[{form:"Perto x Longe",example:"This room is small. That room is big.",pt:"Esta sala é pequena. Aquela sala é grande."},{form:"ONE (singular)",example:"I want this laptop, not that one.",pt:"Quero este notebook, não aquele."},{form:"ONES (plural)",example:"These servers are new. Those ones are old.",pt:"Estes servidores são novos. Aqueles são antigos."}]},reading:{title:"In the Data Center",text:"This is the data center. It is far from the office. These servers are new. Those ones on the wall are old. That window lets in light. This room is always cold because the machines are hot.",translation:"Este é o data center. Ele fica longe do escritório. Estes servidores são novos. Aqueles na parede são antigos. Aquela janela deixa entrar luz. Esta sala é sempre fria porque as máquinas são quentes."},quiz:[{q:"Longe no plural:",options:["this","these","those"],ans:"those"},{q:"Evitar repetição: 'This laptop is new, ___ is old.'",options:["a laptop","one","some"],ans:"one"},{q:"Perto no singular:",options:["this","that","those"],ans:"this"}],chunks:[{en:"this room is cold",pt:"esta sala é fria"},{en:"that window lets in light",pt:"aquela janela deixa entrar luz"},{en:"those ones are old",pt:"aqueles são antigos"}],listeningScript:"Welcome to the data center. These servers process user requests. Those ones on the left are for backups. This one here is brand new. That light is a status indicator.",speakingPrompt:"Descreva sua sala: 'This is my room. That window is far. These chairs are new. Those ones are old.'",lightReading:"A data center is a large room full of servers that store and process data for many users.",journalPrompt:"Today is Day 12. I practiced demonstratives and one/ones.",tip:"DICA DE LISTENING: ao ouvir, tente captar a IDEIA geral primeiro (quem? o quê? onde?), depois os detalhes. Não se prenda a palavras desconhecidas na primeira escuta."},13:{dayName:"Dia 13 — Sábado",title:"Revisão de Artigos & Plurais + TESTE DE SÁBADO 2",focus:"Revisar artigos/plurais/demonstrativos e realizar o teste semanal.",vocab:[{en:"Article",pt:"Artigo (gramática)"},{en:"Plural",pt:"Plural"},{en:"Singular",pt:"Singular"},{en:"Rule",pt:"Regra"},{en:"Example",pt:"Exemplo"},{en:"List",pt:"Lista"},{en:"Check",pt:"Verificar"},{en:"Correct",pt:"Correto"},{en:"Wrong",pt:"Errado"},{en:"Test",pt:"Teste"}],grammar:{title:"Resumo da Semana 2",rule:"A/AN pelo som; THE para específico; zero artigo para geral; plurais -s/-es/-ies e irregulares; this/that/these/those por distância.",table:[{form:"Artigos",example:"an hour, a university, the internet",pt:"uma hora, uma universidade, a internet"},{form:"Plurais",example:"box -> boxes, city -> cities, man -> men",pt:"caixa -> caixas, cidade -> cidades, homem -> homens"},{form:"Demonstrativos",example:"This file, that server, these apps, those users",pt:"este arquivo, aquele servidor, estes apps, aqueles usuários"}]},reading:{title:"Apps on My Phone",text:"I have many apps on my phone. This app is for messages. That one is for maps. These apps are for work. Those ones are games. People use apps every day in many countries. An internet connection is important for most apps.",translation:"Eu tenho muitos apps no meu celular. Este app é para mensagens. Aquele é para mapas. Estes apps são para trabalho. Aqueles são jogos. As pessoas usam apps todos os dias em muitos países. Uma conexão com a internet é importante para a maioria dos apps."},quiz:[{q:"Análise: 'This app, that one' — 'that one' se refere a:",options:["outro app","o mesmo app","um jogo"],ans:"outro app"},{q:"Plural de 'app':",options:["apps","appes","appies"],ans:"apps"},{q:"Complete: '___ users are important' (estes usuários):",options:["This","These","Those"],ans:"These"}],chunks:[{en:"this app is for messages",pt:"este app é para mensagens"},{en:"an internet connection",pt:"uma conexão com a internet"},{en:"most apps",pt:"a maioria dos apps"}],listeningScript:"People use phones all over the world. An internet connection is necessary today. These apps are useful. That one is a game. Many users download new apps every week.",speakingPrompt:"Fale sobre seus apps: 'This app is for work. That one is a game. These apps are useful.'",lightReading:"Most modern applications need an internet connection to fetch data from servers.",journalPrompt:"Today is Day 13. I completed my second Saturday Test!",tip:"DICA DE APRENDIZADO: ensine o que você aprendeu (Técnica Feynman). Explique a regra de artigos para alguém, mesmo em português. Quem explica, consolida."},14:{dayName:"Dia 14 — Domingo",title:"Revisão Geral da Semana 2 & Imersão Leve",focus:"Consolidar a Semana 2 e praticar leitura leve.",vocab:[{en:"Sentence",pt:"Frase"},{en:"Word",pt:"Palavra"},{en:"Meaning",pt:"Significado"},{en:"Book",pt:"Livro"},{en:"Article",pt:"Artigo / Texto"},{en:"Story",pt:"História"},{en:"Title",pt:"Título"},{en:"Author",pt:"Autor(a)"},{en:"Page",pt:"Página"},{en:"Note",pt:"Anotação"}],grammar:{title:"Checkpoint 14 — O que você já domina",rule:"Você já apresenta pessoas, descreve objetos, fala de posse e pluraliza palavras. Isso é o coração do nível A1 inicial.",table:[{form:"Apresentar",example:"This is Ana. She is a developer.",pt:"Esta é a Ana. Ela é desenvolvedora."},{form:"Descrever",example:"That laptop is fast. Those files are old.",pt:"Aquele notebook é rápido. Aqueles arquivos são antigos."},{form:"Artigos",example:"I read an article about the internet.",pt:"Li um artigo sobre a internet."}]},reading:{title:"A Quiet Sunday",text:"It is Sunday. I read a book in the afternoon. The book is about computers. I also read an article on my phone. The article is about new technology. I write notes with a pen. Notes help me remember words and sentences.",translation:"É domingo. Eu leio um livro à tarde. O livro é sobre computadores. Também leio um artigo no meu celular. O artigo é sobre novas tecnologias. Eu escrevo anotações com uma caneta. As anotações me ajudam a lembrar palavras e frases."},quiz:[{q:"'I read a book' — 'a' porque:",options:["livro específico","um livro qualquer","livro no plural"],ans:"um livro qualquer"},{q:"'an article' — 'an' porque:",options:["som de vogal","som de consoante","é plural"],ans:"som de vogal"},{q:"Complete: 'Notes help me ___ words.'",options:["remember","remembering","remembers"],ans:"remember"}],chunks:[{en:"read a book",pt:"ler um livro"},{en:"write notes",pt:"fazer anotações"},{en:"remember words",pt:"lembrar palavras"}],listeningScript:"On Sundays, I relax. I read a book and write notes. Notes are very useful. They help me remember new English words. I read every page slowly.",speakingPrompt:"Conte sua rotina de domingo: 'On Sunday I read a book. I write notes. Notes help me.'",lightReading:"Reading regularly is the fastest way to increase vocabulary because words appear in context.",journalPrompt:"Today is Day 14. I finished Week 2. My foundation is growing!",tip:"DICA DE LEITURA: sublinhe 3 palavras novas no texto e escreva o significado ao lado. Nunca traduza o texto todo — só o que for essencial. Tradução total trava a fluência."},15:{dayName:"Dia 15 — Segunda-feira",title:"Adjetivos Possessivos na Prática",focus:"Usar my, your, his, her, its, our, their com naturalidade em frases do dia a dia.",vocab:[{en:"Key",pt:"Chave"},{en:"Password",pt:"Senha"},{en:"Account",pt:"Conta"},{en:"Profile",pt:"Perfil"},{en:"Phone",pt:"Celular"},{en:"Car",pt:"Carro"},{en:"House",pt:"Casa"},{en:"Money",pt:"Dinheiro"},{en:"Time",pt:"Tempo"},{en:"Job",pt:"Trabalho / Emprego"}],grammar:{title:"Adjetivos Possessivos",rule:"Vêm SEMPRE antes do nome e não mudam com gênero: my phone, her phone. NUNCA usamos 'the' junto: 'the my phone' é ERRO.",table:[{form:"my / your",example:"This is my key. Is that your password?",pt:"Esta é minha chave. Aquela é sua senha?"},{form:"his / her",example:"His job is great. Her account is active.",pt:"O emprego dele é ótimo. A conta dela está ativa."},{form:"its / our / their",example:"The company protects its data. Our house is small. Their car is new.",pt:"A empresa protege seus dados. Nossa casa é pequena. O carro deles é novo."}]},reading:{title:"My Digital Life",text:"I have my own account on every website. My password is strong. I keep it in my phone. My colleague keeps his password in a notebook. Her password is very long. We protect our data every day.",translation:"Eu tenho minha própria conta em todos os sites. Minha senha é forte. Eu a mantenho no meu celular. Meu colega mantém a senha dele em um caderno. A senha dela é muito longa. Protegemos nossos dados todos os dias."},quiz:[{q:"'___ password is strong' (minha):",options:["My","Your","His"],ans:"My"},{q:"'Ana: ___ account is active' (dela):",options:["her","his","its"],ans:"her"},{q:"Errado em inglês:",options:["my phone","the my phone","your phone"],ans:"the my phone"}],chunks:[{en:"my own account",pt:"minha própria conta"},{en:"protect our data",pt:"proteger nossos dados"},{en:"keep it in my phone",pt:"mantê-lo no meu celular"}],listeningScript:"This is my phone. Your phone is on the desk. His data is safe. Her password is strong. Our accounts are protected. Their company is secure.",speakingPrompt:"Apresente suas coisas: 'This is my phone. This is my key. Her name is Ana. Their office is big.'",lightReading:"Strong passwords protect user accounts from unauthorized access in digital systems.",journalPrompt:"Today is Day 15. I practiced possessive adjectives all day long.",tip:"DICA DE ESCRITA: uma das frases-modelo mais úteis: 'This is my [coisa]. That is your [coisa].' Substitua a [coisa] por 10 palavras diferentes hoje."},16:{dayName:"Dia 16 — Terça-feira",title:"Pronomes Possessivos (Mine, Yours, His...)",focus:"Distinguir my (adj.) de mine (pronome) e usar corretamente.",vocab:[{en:"Mine",pt:"Meu (pronome)"},{en:"Yours",pt:"Seu (pronome)"},{en:"Hers",pt:"Dela (pronome)"},{en:"Ours",pt:"Nosso (pronome)"},{en:"Theirs",pt:"Deles (pronome)"},{en:"Yours (plural)",pt:"De vocês"},{en:"Ours",pt:"Nosso"},{en:"Own",pt:"Próprio"},{en:"Belong",pt:"Pertencer"},{en:"Laptop",pt:"Notebook"}],grammar:{title:"Pronomes Possessivos",rule:"MINE, YOURS, HIS, HERS, OURS, THEIRS substituem 'my + nome': 'This laptop is mine' = 'This is my laptop'. Nunca colocamos um nome depois de mine.",table:[{form:"mine (meu)",example:"This laptop is mine.",pt:"Este notebook é meu."},{form:"yours / hers / ours",example:"Is this key yours? No, it is hers. The code is ours.",pt:"Esta chave é sua? Não, é dela. O código é nosso."},{form:"Adjetivo vs Pronome",example:"my code (adj.) / the code is mine (pron.)",pt:"meu código / o código é meu"}]},reading:{title:"Whose Laptop Is This?",text:"There are two laptops on the table. 'Is this one yours?' asks Maria. 'No, mine is the black one. That laptop is hers,' I answer. Our team shares the office. The white laptop belongs to Lucas. It is his.",translation:"Há dois notebooks na mesa. 'Este é seu?' pergunta Maria. 'Não, o meu é o preto. Aquele notebook é dela', respondo. Nossa equipe compartilha o escritório. O notebook branco pertence ao Lucas. É dele."},quiz:[{q:"Correto:",options:["This is mine laptop","This laptop is mine","This mine laptop"],ans:"This laptop is mine"},{q:"'O código é nosso':",options:["The code is ours","The code is our","The our code"],ans:"The code is ours"},{q:"'É dela':",options:["It is hers","It is her","It is She"],ans:"It is hers"}],chunks:[{en:"this laptop is mine",pt:"este notebook é meu"},{en:"it belongs to him",pt:"pertence a ele"},{en:"the code is ours",pt:"o código é nosso"}],listeningScript:"Whose phone is this? It is not mine. Is it yours? No, it is hers. Okay, the phone is hers. The keys are his. Everything here is ours.",speakingPrompt:"Apresente posse: 'This book is mine. That pen is yours. This phone is hers.'",lightReading:"Possessive pronouns replace the noun completely: 'mine' never appears before another noun.",journalPrompt:"Today is Day 16. I learned the difference between my and mine.",tip:"DICA DE MEMÓRIA: 'my' SEMPRE vem antes de substantivo; 'mine' SEMPRE sozinho. Essa âncora elimina metade dos erros de possessivo para sempre."},17:{dayName:"Dia 17 — Quarta-feira",title:"Genitivo 'S (Posse Apóstrofo)",focus:"Expressar posse com 's e s' (John's computer, the developers' code).",vocab:[{en:"Owner",pt:"Dono(a)"},{en:"Possession",pt:"Posse"},{en:"Apostrophe",pt:"Apóstrofo"},{en:"Brother",pt:"Irmão"},{en:"Sister",pt:"Irmã"},{en:"Friend",pt:"Amigo(a)"},{en:"Colleague",pt:"Colega"},{en:"Boss",pt:"Chefe"},{en:"Client",pt:"Cliente"},{en:"Team leader",pt:"Líder de equipe"}],grammar:{title:"Genitive Case ('s)",rule:"Substantivo + 's indica posse: John's computer. Para plural terminado em S: só apóstrofo: the developers' code. Para seres não vivos, preferimos OF: the color of the screen.",table:[{form:"Singular + 's",example:"John's computer, the boss's office",pt:"o computador do John, o escritório do chefe"},{form:"Plural em S + '",example:"the developers' code, my parents' house",pt:"o código dos desenvolvedores, a casa dos meus pais"},{form:"Coisa + of",example:"the color of the screen",pt:"a cor da tela"}]},reading:{title:"My Friend's Project",text:"My friend's laptop is very fast. My colleague's office is on the third floor. The boss's meeting starts at ten. Our clients' data is protected. The developer's code is clean and organized.",translation:"O notebook do meu amigo é muito rápido. O escritório do meu colega fica no terceiro andar. A reunião do chefe começa às dez. Os dados dos nossos clientes são protegidos. O código do desenvolvedor é limpo e organizado."},quiz:[{q:"'O computador do John':",options:["John's computer","the computer of John's","John computer"],ans:"John's computer"},{q:"'O código dos devs':",options:["the developers's code","the developers' code","the developer code"],ans:"the developers' code"},{q:"'A cor da tela':",options:["the screen's color","the color of the screen","the color screen's"],ans:"the color of the screen"}],chunks:[{en:"my friend's laptop",pt:"o notebook do meu amigo"},{en:"the developers' code",pt:"o código dos desenvolvedores"},{en:"the boss's office",pt:"o escritório do chefe"}],listeningScript:"This is my brother's phone. My sister's computer is new. The client's project is important. The team's goal is clear. Everybody respects the boss's decisions.",speakingPrompt:"Fale sobre posse: 'My brother's car is fast. My sister's phone is new. The client's project is big.'",lightReading:"In object-oriented programming, an object's data belongs to that instance — same concept as the genitive: the object's data.",journalPrompt:"Today is Day 17. I learned the genitive with apostrophe S.",tip:"DICA DE LEITURA: no texto, o apóstrofo mostra posse. Ao ler 'my friend's laptop', entenda 'notebook DO meu amigo' — a ordem inversa do português. Treine isso em 10 frases."},18:{dayName:"Dia 18 — Quinta-feira",title:"Preposições de Lugar: IN, ON, AT",focus:"Usar as 3 preposições mais comuns de lugar com regras claras.",vocab:[{en:"In",pt:"Em / Dentro de"},{en:"On",pt:"Sobre / Em cima de"},{en:"At",pt:"Em (ponto específico)"},{en:"City",pt:"Cidade"},{en:"Street",pt:"Rua"},{en:"Floor",pt:"Andar"},{en:"Corner",pt:"Esquina"},{en:"Building",pt:"Prédio"},{en:"Room",pt:"Sala"},{en:"Office",pt:"Escritório"}],grammar:{title:"IN / ON / AT (Lugar)",rule:"IN = dentro (in the room, in the city). ON = em cima/superfície (on the table, on the floor). AT = ponto específico (at the office, at the corner).",table:[{form:"IN (dentro)",example:"The server is in the building.",pt:"O servidor está dentro do prédio."},{form:"ON (superfície)",example:"The laptop is on the desk.",pt:"O notebook está em cima da mesa."},{form:"AT (ponto)",example:"She is at the office.",pt:"Ela está no escritório."}]},reading:{title:"Where Is Everything?",text:"My office is on the third floor. My laptop is on the desk. The router is in the corner of the room. My colleague is at the meeting in Meeting Room B. The main server is in the data center on the first floor.",translation:"Meu escritório fica no terceiro andar. Meu notebook está em cima da mesa. O roteador está no canto da sala. Meu colega está na reunião na Sala B. O servidor principal está no data center no primeiro andar."},quiz:[{q:"Complete: 'The book is ___ the table.'",options:["in","on","at"],ans:"on"},{q:"Complete: 'He works ___ the office.'",options:["in","on","at"],ans:"at"},{q:"Complete: 'We live ___ Brazil.'",options:["in","on","at"],ans:"in"}],chunks:[{en:"on the third floor",pt:"no terceiro andar"},{en:"in the corner",pt:"no canto"},{en:"at the office",pt:"no escritório"}],listeningScript:"Where is Ana? She is in the meeting room on the second floor. The laptop is on the table. The team is at the office today. The files are in the folder.",speakingPrompt:"Descreva seu ambiente: 'My phone is on the table. I am in my room. We are at home.'",lightReading:"IN is for closed spaces, ON for surfaces, and AT for specific points — the same logic applies in code: data in memory, apps on servers, requests at endpoints.",journalPrompt:"Today is Day 18. I learned IN, ON and AT for places.",tip:"DICA DE MEMÓRIA: pense em caixas: IN = dentro da caixa; ON = em cima da caixa; AT = ao lado do endereço da caixa. Três imagens mentais substituem três regras decoradas."},19:{dayName:"Dia 19 — Sexta-feira",title:"Outras Preposições de Lugar",focus:"Ampliar o repertório: under, next to, between, behind, in front of, above.",vocab:[{en:"Under",pt:"Embaixo de"},{en:"Next to",pt:"Ao lado de"},{en:"Between",pt:"Entre"},{en:"Behind",pt:"Atrás de"},{en:"In front of",pt:"Em frente de"},{en:"Above",pt:"Acima de"},{en:"Below",pt:"Abaixo de"},{en:"Left",pt:"Esquerda"},{en:"Right",pt:"Direita"},{en:"Outside",pt:"Fora"}],grammar:{title:"Preposições de Posição",rule:"UNDER (embaixo), NEXT TO (ao lado), BETWEEN (entre dois), BEHIND (atrás), IN FRONT OF (em frente), ABOVE (acima), BELOW (abaixo).",table:[{form:"under / next to",example:"The mouse is under the desk. The router is next to the TV.",pt:"O mouse está embaixo da mesa. O roteador está ao lado da TV."},{form:"between / behind",example:"The keyboard is between the phone and the laptop. The server is behind the door.",pt:"O teclado está entre o celular e o notebook. O servidor está atrás da porta."},{form:"in front of / above",example:"She sits in front of the screen. The camera is above the monitor.",pt:"Ela se senta em frente à tela. A câmera está acima do monitor."}]},reading:{title:"My Desk Setup",text:"The monitor is on the desk. The keyboard is in front of the monitor. The mouse is next to the keyboard. The laptop is under the desk, closed. The router sits between the desk and the wall. The camera is above the screen.",translation:"O monitor está em cima da mesa. O teclado está em frente ao monitor. O mouse está ao lado do teclado. O notebook está embaixo da mesa, fechado. O roteador fica entre a mesa e a parede. A câmera está acima da tela."},quiz:[{q:"'The mouse is ___ the desk' (embaixo):",options:["next to","under","above"],ans:"under"},{q:"'Entre a mesa e a parede':",options:["between the desk and the wall","behind the desk and the wall","in front of the wall"],ans:"between the desk and the wall"},{q:"'Ao lado do teclado':",options:["behind the keyboard","next to the keyboard","above the keyboard"],ans:"next to the keyboard"}],chunks:[{en:"in front of the monitor",pt:"em frente ao monitor"},{en:"between the desk and the wall",pt:"entre a mesa e a parede"},{en:"above the screen",pt:"acima da tela"}],listeningScript:"Look at my desk. The screen is in front of me. The phone is next to the keyboard. The router is above the cabinet. Everything is under control.",speakingPrompt:"Descreva 5 posições na sua mesa: 'The pen is next to the notebook. The lamp is above me.'",lightReading:"In CSS, elements are placed with absolute or relative positioning — precisely like prepositions: above, below, next to.",journalPrompt:"Today is Day 19. I can describe where things are in English.",tip:"DICA DE LEITURA: visualize! Ao ler 'under the desk', forme a imagem mental. A leitura com imagens retém 3x mais e ajuda a não traduzir palavra por palavra."},20:{dayName:"Dia 20 — Sábado",title:"Revisão de Posse & Preposições + TESTE DE SÁBADO 3",focus:"Revisar possessivos e preposições, e realizar o teste semanal.",vocab:[{en:"Place",pt:"Lugar"},{en:"Position",pt:"Posição"},{en:"Direction",pt:"Direção"},{en:"Map",pt:"Mapa"},{en:"Park",pt:"Parque"},{en:"Hospital",pt:"Hospital"},{en:"School",pt:"Escola"},{en:"Station",pt:"Estação"},{en:"Market",pt:"Mercado"},{en:"Bank",pt:"Banco"}],grammar:{title:"Resumo da Semana 3",rule:"Posse: my/mine/'s/of. Lugar: in/on/at, under, next to, between, behind, in front of, above.",table:[{form:"Posse",example:"This laptop is mine. Maria's desk is next to mine.",pt:"Este notebook é meu. A mesa da Maria é ao lado da minha."},{form:"IN / ON / AT",example:"The bank is in the city center, on Main Street, at number 25.",pt:"O banco fica no centro da cidade, na Rua Principal, no número 25."},{form:"Posição",example:"The hospital is behind the park. The station is between the market and the bank.",pt:"O hospital fica atrás do parque. A estação fica entre o mercado e o banco."}]},reading:{title:"Finding the Way",text:"The new office is in the city center. It is on Main Street, next to the bank. The metro station is in front of the building. The park is behind the hospital. I look at the map on my phone. Our office is between the market and the station.",translation:"O novo escritório fica no centro da cidade. Fica na Rua Principal, ao lado do banco. A estação de metrô fica em frente ao prédio. O parque fica atrás do hospital. Eu olho o mapa no meu celular. Nosso escritório fica entre o mercado e a estação."},quiz:[{q:"'Em frente ao prédio':",options:["behind the building","in front of the building","above the building"],ans:"in front of the building"},{q:"Correto:",options:["My sister's house is big","The house is my sister","Sister's my house is big"],ans:"My sister's house is big"},{q:"'A estação fica entre o mercado e o banco':",options:["between the market and the bank","next to the market or the bank","in front of the bank market"],ans:"between the market and the bank"}],chunks:[{en:"in the city center",pt:"no centro da cidade"},{en:"next to the bank",pt:"ao lado do banco"},{en:"look at the map",pt:"olhar o mapa"}],listeningScript:"Our new office is in the city center. It is on Main Street, next to the bank. The station is in front of us. You can see the park behind the hospital. Follow the map.",speakingPrompt:"Explique o caminho até sua casa: 'My house is in the city. It is next to the park. The station is behind it.'",lightReading:"Maps convert abstract coordinates into spatial relationships: next to, between, behind — navigation is a language of prepositions.",journalPrompt:"Today is Day 20. I completed my third Saturday Test!",tip:"DICA DE APRENDIZADO: ative a leitura em voz alta. Ler 5 frases em voz alta exercita a boca, o ouvido e os olhos ao mesmo tempo — o pacote completo de aprendizagem."},21:{dayName:"Dia 21 — Domingo",title:"Revisão Geral da Semana 3 & Imersão Leve",focus:"Consolidar a Semana 3 e revisar por meio de leitura e escuta leves.",vocab:[{en:"Review",pt:"Revisão"},{en:"Summary",pt:"Resumo"},{en:"Remember",pt:"Lembrar"},{en:"Forget",pt:"Esquecer"},{en:"Practice",pt:"Praticar"},{en:"Repeat",pt:"Repetir"},{en:"Improve",pt:"Melhorar"},{en:"Learn",pt:"Aprender"},{en:"Study",pt:"Estudar"},{en:"Speak",pt:"Falar"}],grammar:{title:"Checkpoint 21 — Você já descreve lugares",rule:"Você sabe dizer onde as coisas estão, de quem são e o que são. Base de qualquer conversa de suporte técnico ou apresentação de escritório.",table:[{form:"Onde está?",example:"Where is the router? It is behind the monitor.",pt:"Onde está o roteador? Está atrás do monitor."},{form:"De quem é?",example:"Whose phone is this? It is mine.",pt:"De quem é este celular? É meu."},{form:"O que é?",example:"This is my boss's laptop. It is new.",pt:"Este é o notebook do meu chefe. É novo."}]},reading:{title:"Sunday Review",text:"Today I review everything. I say: this laptop is mine. My desk is in front of the window. The router is next to the printer. I practice the words and repeat them. Practice helps me remember.",translation:"Hoje eu reviso tudo. Eu digo: este notebook é meu. Minha mesa fica em frente à janela. O roteador está ao lado da impressora. Pratico as palavras e as repito. A prática me ajuda a lembrar."},quiz:[{q:"'My desk is ___ the window' (em frente):",options:["in front of","behind","under"],ans:"in front of"},{q:"Complete: 'Practice helps me ___':",options:["remember","remembered","remembering"],ans:"remember"},{q:"'De quem é?' em inglês:",options:["Whose is this?","Who is this?","Where is this?"],ans:"Whose is this?"}],chunks:[{en:"I review everything",pt:"eu reviso tudo"},{en:"practice helps me remember",pt:"a prática me ajuda a lembrar"},{en:"I repeat the words",pt:"eu repito as palavras"}],listeningScript:"Sunday is my review day. I practice every word. I repeat the sentences and listen to the audio again. Review every week. Practice makes progress.",speakingPrompt:"Faça seu resumo oral: 'This week I studied possessives and prepositions. My desk is next to the window.'",lightReading:"Repetition with spacing (reviewing at intervals) is scientifically proven to move words into long-term memory.",journalPrompt:"Today is Day 21. Week 3 is complete. I can describe places now!",tip:"DICA DE APRENDIZADO: a regra do 20/80: 20% do estudo deve ser aprender COISA NOVA; 80% deve ser REVISAR. Se sua semana está 100% novidade, você está esquecendo o que aprendeu."},22:{dayName:"Dia 22 — Segunda-feira",title:"There Is / There Are (Existir)",focus:"Dizer o que existe e o que não existe usando there is / there are.",vocab:[{en:"There is",pt:"Há / Existe (singular)"},{en:"There are",pt:"Há / Existem (plural)"},{en:"Printer",pt:"Impressora"},{en:"Scanner",pt:"Scanner"},{en:"Cabinet",pt:"Armário"},{en:"Chair",pt:"Cadeira"},{en:"Lamp",pt:"Abajur / Lâmpada"},{en:"Cable",pt:"Cabo"},{en:"Battery",pt:"Bateria"},{en:"Charger",pt:"Carregador"}],grammar:{title:"There Is / There Are",rule:"THERE IS + singular (there is a printer). THERE ARE + plural (there are two printers). Negativa: there isn't / there aren't. Pergunta: Is there...? Are there...?",table:[{form:"Afirmativa",example:"There is a printer in the room.",pt:"Há uma impressora na sala."},{form:"Negativa",example:"There aren't many cables.",pt:"Não há muitos cabos."},{form:"Pergunta",example:"Is there a charger? Are there batteries?",pt:"Há um carregador? Há baterias?"}],foundation:{title:"Existe algo, mas não importa quem faz a ação",explanation:"Use THERE IS/ARE quando quer apresentar a existência de algo em um lugar. Não é o mesmo que 'it is': THERE IS apresenta que algo existe; IT IS fala de uma coisa já conhecida.",steps:["Uma coisa: There is a printer.","Várias coisas: There are two printers.","Pergunta: mova IS/ARE: Is there a printer? Are there printers?"],warning:"Não diga 'There have'. Para existência, use THERE IS ou THERE ARE."}},reading:{title:"What Is in the Office?",text:"In my office, there is a big desk and a comfortable chair. There are two monitors on the desk. There is a printer next to the cabinet. There isn't a scanner, but there are many cables and one charger. Is there a lamp? Yes, there is.",translation:"No meu escritório, há uma mesa grande e uma cadeira confortável. Há dois monitores em cima da mesa. Há uma impressora ao lado do armário. Não há scanner, mas há muitos cabos e um carregador. Há um abajur? Sim, há."},quiz:[{q:"Complete: '___ a printer in the room.'",options:["There is","There are","Is there"],ans:"There is"},{q:"Complete: '___ two monitors.'",options:["There is","There are","Are"],ans:"There are"},{q:"Pergunta correta:",options:["Are there a lamp?","Is there a lamp?","There is a lamp?"],ans:"Is there a lamp?"}],chunks:[{en:"there is a printer",pt:"há uma impressora"},{en:"there are two monitors",pt:"há dois monitores"},{en:"is there a lamp?",pt:"há um abajur?"}],listeningScript:"In the new office there is a meeting room. There are three desks and many chairs. There isn't a printer yet. Is there a whiteboard? Yes, there is one on the wall.",speakingPrompt:"Descreva seu quarto: 'In my room there is a bed. There are two windows. There isn't a TV.'",lightReading:"In programming, 'there is/there are' maps to existence checks: if there is a file, load it; if there aren't any records, show an empty state.",journalPrompt:"Today is Day 22. I learned there is and there are.",tip:"DICA DE ESCRITA: frases com 'there is/are' são perfeitas para começar descrições. Abra qualquer descrição com elas: 'There is/are...' — é o padrão dos nativos em e-mails e documentação."},23:{dayName:"Dia 23 — Terça-feira",title:"Have / Has (Ter & Possuir)",focus:"Usar have e has para posse, características e necessidades.",vocab:[{en:"Have",pt:"Ter"},{en:"Has",pt:"Tem (ele/ela)"},{en:"Fever",pt:"Febre"},{en:"Idea",pt:"Ideia"},{en:"Question",pt:"Pergunta"},{en:"Answer",pt:"Resposta"},{en:"Problem",pt:"Problema"},{en:"Solution",pt:"Solução"},{en:"Experience",pt:"Experiência"},{en:"Knowledge",pt:"Conhecimento"}],grammar:{title:"Have / Has",rule:"HAVE para I, you, we, they. HAS para he, she, it. Negativa: don't have / doesn't have. Pergunta: Do you have...? Does she have...?",table:[{form:"Afirmativa",example:"I have an idea. She has experience.",pt:"Eu tenho uma ideia. Ela tem experiência."},{form:"Negativa",example:"We don't have the answer. He doesn't have a solution.",pt:"Nós não temos a resposta. Ele não tem uma solução."},{form:"Pergunta",example:"Do you have any questions? Does it have a battery?",pt:"Você tem alguma pergunta? Ele tem bateria?"}],foundation:{title:"HAS só na frase afirmativa de he/she/it",explanation:"HAVE é o verbo principal. Na frase afirmativa, he/she/it pede HAS. Quando DO/DOES entra para negar ou perguntar, ele assume essa marca; por isso HAVE volta à forma base.",steps:["She has a charger. (afirmativa)","She does not have a charger. (negação)","Does she have a charger? (pergunta)"],warning:"Nunca use 'does she has' ou 'she doesn't has': depois de DOES/DOESN'T, o verbo é HAVE."}},reading:{title:"A Problem and a Solution",text:"Ana has a problem with her laptop. The battery doesn't work. She doesn't have a charger at the office. We have an old charger in the cabinet. Does it have the right cable? Yes, it does. She has a solution now.",translation:"Ana tem um problema com o notebook dela. A bateria não funciona. Ela não tem um carregador no escritório. Nós temos um carregador antigo no armário. Ele tem o cabo certo? Sim, tem. Ela tem uma solução agora."},quiz:[{q:"Complete: 'She ___ a problem.'",options:["have","has","having"],ans:"has"},{q:"Complete: 'We ___ the answer.'",options:["has","have","haves"],ans:"have"},{q:"Pergunta correta:",options:["Do she have a charger?","Does she have a charger?","Does she has a charger?"],ans:"Does she have a charger?"}],chunks:[{en:"I have an idea",pt:"tenho uma ideia"},{en:"she has a solution",pt:"ela tem uma solução"},{en:"do you have any questions?",pt:"você tem alguma pergunta?"}],listeningScript:"Do you have the report? Yes, I have it. Does she have the password? No, she doesn't. We have a meeting in an hour. They have a new project.",speakingPrompt:"Fale sobre o que você tem: 'I have a laptop. I don't have a tablet. She has a new phone.'",lightReading:"In data models, 'has' expresses relationships: a user has an account; an account has credentials — same possession concept in English grammar.",journalPrompt:"Today is Day 23. I learned have and has.",tip:"DICA DE MEMÓRIA: HAS só existe em 3 casos: he, she, it. Memorize 'HE-SHE-IT HAS'. Todo o resto é HAVE, inclusive 'you' e 'they'."},24:{dayName:"Dia 24 — Quarta-feira",title:"Present Simple — Afirmativa (Rotina & Hábitos)",focus:"Falar sobre rotina diária com o Present Simple e o -s da 3ª pessoa.",vocab:[{en:"Wake up",pt:"Acordar"},{en:"Work",pt:"Trabalhar"},{en:"Study",pt:"Estudar"},{en:"Write",pt:"Escrever"},{en:"Read",pt:"Ler"},{en:"Start",pt:"Começar"},{en:"Finish",pt:"Terminar"},{en:"Help",pt:"Ajudar"},{en:"Need",pt:"Precisar"},{en:"Use",pt:"Usar"}],grammar:{title:"Present Simple (3ª Pessoa -S)",rule:"I/you/we/they use o verbo base (I work). He/she/it ganha -s ou -es (she works, he studies -y -> -ies, it does, it goes).",table:[{form:"I / You / We / They",example:"I work every day. They use Linux.",pt:"Eu trabalho todos os dias. Eles usam Linux."},{form:"He / She / It + -s",example:"She works at a startup. He studies at night.",pt:"Ela trabalha numa startup. Ele estuda à noite."},{form:"-y -> -ies / -es",example:"He studies. She goes home. It finishes at six.",pt:"Ele estuda. Ela vai para casa. Termina às seis."}],foundation:{title:"O marcador da terceira pessoa",explanation:"No Present Simple, o inglês marca uma ação feita por he, she ou it com -s. Essa marca mostra quem realiza o hábito; os outros sujeitos usam o verbo normal.",steps:["I work / You work / They work.","He works / She works / It works.","Se terminar em consoante + y: study → studies."],warning:"O -s aparece só na afirmativa. Nos próximos dias você verá que ele sai depois de DOES/DOESN'T."}},reading:{title:"My Daily Routine",text:"Every day I wake up at seven. I study English in the morning. My brother works at a tech company. He starts at nine and finishes at six. She, my sister, helps him on weekends. I use my laptop for everything.",translation:"Todos os dias eu acordo às sete. Eu estudo inglês de manhã. Meu irmão trabalha numa empresa de tecnologia. Ele começa às nove e termina às seis. Minha irmã ajuda ele nos fins de semana. Eu uso meu notebook para tudo."},quiz:[{q:"Complete: 'She ___ at a startup.'",options:["work","works","working"],ans:"works"},{q:"Complete: 'He ___ at night.'",options:["study","studies","studys"],ans:"studies"},{q:"Complete: 'I ___ English every day.'",options:["study","studies","studying"],ans:"study"}],chunks:[{en:"I wake up at seven",pt:"acordo às sete"},{en:"he starts at nine",pt:"ele começa às nove"},{en:"she finishes at six",pt:"ela termina às seis"}],listeningScript:"My routine is simple. I wake up at six thirty. I study and work in the morning. My sister works from home. She starts at eight. We all use computers all day.",speakingPrompt:"Conte sua rotina: 'I wake up at [hora]. I study in the morning. I use my computer at night.'",lightReading:"Routine verbs describe habitual actions: compile, deploy, test — developers run these tasks on schedule every day.",journalPrompt:"Today is Day 24. I learned the Present Simple.",tip:"DICA DE ESCRITA: a 3ª pessoa com -s é o erro nº 1 do brasileiro. Ao escrever 'She work', seu cérebro precisa de alarme. Faça uma regra de ouro: he/she/it = verbo COM -s."},25:{dayName:"Dia 25 — Quinta-feira",title:"Present Simple — Negativa (Don't / Doesn't)",focus:"Negar ações habituais corretamente com don't e doesn't.",vocab:[{en:"Don't",pt:"Não (eu, você, nós, eles)"},{en:"Doesn't",pt:"Não (ele, ela)"},{en:"Like",pt:"Gostar"},{en:"Know",pt:"Saber / Conhecer"},{en:"Understand",pt:"Entender"},{en:"Speak",pt:"Falar (idioma)"},{en:"Live",pt:"Morar"},{en:"Play",pt:"Jogar / Tocar"},{en:"Watch",pt:"Assistir"},{en:"Listen",pt:"Ouvir"}],grammar:{title:"Present Simple Negativo",rule:"DO NOT (don't) + verbo base para I/you/we/they. DOES NOT (doesn't) + verbo base para he/she/it. Com doesn't, o verbo perde o -s.",table:[{form:"Don't + verbo base",example:"I don't like coffee. We don't watch TV.",pt:"Eu não gosto de café. Nós não assistimos TV."},{form:"Doesn't + verbo base",example:"She doesn't speak English. He doesn't play games.",pt:"Ela não fala inglês. Ele não joga games."},{form:"Atenção ao -s",example:"He works -> He doesn't work (sem s!)",pt:"Ele trabalha -> Ele não trabalha"}],foundation:{title:"Por que o -s desaparece em DOESN'T?",explanation:"DO e DOES são auxiliares: eles carregam a estrutura de negação e pergunta. DOES já mostra que o sujeito é he/she/it, então o verbo principal não repete o -s.",steps:["Afirmativa: She works.","Negativa: She does not work.","Não existe: She doesn't works."],warning:"Não misture TO BE e DO: para rotina diga 'She doesn't work'; 'She isn't work' está errado."}},reading:{title:"What I Don't Do",text:"I don't watch TV during the week. My brother doesn't listen to podcasts. He prefers music. My sister doesn't live here. She lives in another city. We don't play video games at work. We don't work on Sundays.",translation:"Eu não assisto TV durante a semana. Meu irmão não ouve podcasts. Ele prefere música. Minha irmã não mora aqui. Ela mora em outra cidade. Nós não jogamos videogames no trabalho. Nós não trabalhamos aos domingos."},quiz:[{q:"Complete: 'I ___ like coffee.'",options:["don't","doesn't","not"],ans:"don't"},{q:"Complete: 'She ___ speak English.'",options:["don't","doesn't","isn't"],ans:"doesn't"},{q:"Correto:",options:["He doesn't works","He doesn't work","He don't work"],ans:"He doesn't work"}],chunks:[{en:"I don't like coffee",pt:"não gosto de café"},{en:"she doesn't speak English",pt:"ela não fala inglês"},{en:"we don't work on Sundays",pt:"não trabalhamos aos domingos"}],listeningScript:"Our team works from home. We don't go to the office on Mondays. Mark doesn't join the morning call. He doesn't like early meetings. I don't mind them.",speakingPrompt:"Fale o que você NÃO faz: 'I don't watch TV at night. She doesn't listen to music at work.'",lightReading:"Negative logic is everywhere in code: if the file doesn't exist, create it; if the user doesn't have permission, deny access.",journalPrompt:"Today is Day 25. I learned negative sentences with don't and doesn't.",tip:"DICA DE LEITURA: preste atenção nos 'don't/doesn't' ao ler. Eles mudam o sentido completo da frase. Sublinhe todas as negações dos textos por uma semana — você treinará o radar da negação."},26:{dayName:"Dia 26 — Sexta-feira",title:"Present Simple — Perguntas (Do / Does)",focus:"Fazer perguntas de rotina e responder com respostas curtas.",vocab:[{en:"Usually",pt:"Geralmente"},{en:"Always",pt:"Sempre"},{en:"Sometimes",pt:"Às vezes"},{en:"Never",pt:"Nunca"},{en:"Often",pt:"Frequentemente"},{en:"Morning",pt:"Manhã"},{en:"Afternoon",pt:"Tarde"},{en:"Evening",pt:"Noite (início)"},{en:"Night",pt:"Noite (tarde)"},{en:"Weekend",pt:"Fim de semana"}],grammar:{title:"Perguntas com Do / Does",rule:"DO + sujeito + verbo (Do you work?). DOES + he/she/it (Does she work?). O verbo volta à base. Respostas curtas: Yes, I do. / No, I don't. / Yes, she does. / No, he doesn't.",table:[{form:"Do + I/you/we/they",example:"Do you study at night? Yes, I do.",pt:"Você estuda à noite? Sim."},{form:"Does + he/she/it",example:"Does she work on weekends? No, she doesn't.",pt:"Ela trabalha nos fins de semana? Não."},{form:"Ordem",example:"Do they use Linux? Does it work?",pt:"Eles usam Linux? Funciona?"}],foundation:{title:"O auxiliar abre perguntas de ações e hábitos",explanation:"Com ações como work, study e like, não movemos o verbo principal para a frente. Colocamos DO ou DOES primeiro. É diferente das perguntas com To Be, em que AM/IS/ARE vai para a frente.",steps:["Frase: You study English.","Pergunta: Do you study English?","Frase: She studies English. Pergunta: Does she study English?"],warning:"Não diga 'Study you English?' nem 'Does she studies?'. Use DO/DOES + sujeito + verbo base."}},reading:{title:"Questions About Habits",text:"Do you study English every day? Yes, I do. Does your friend practice at night? No, he doesn't. Does your sister work? Yes, she usually works in the morning. Do we need to bring laptops? No, we don't. The company has computers.",translation:"Você estuda inglês todos os dias? Sim. Seu amigo pratica à noite? Não. Sua irmã trabalha? Sim, ela geralmente trabalha de manhã. Precisamos trazer notebooks? Não. A empresa tem computadores."},quiz:[{q:"Complete: '___ you study at night?'",options:["Do","Does","Are"],ans:"Do"},{q:"Complete: '___ she work on weekends?'",options:["Do","Does","Is"],ans:"Does"},{q:"Resposta curta de 'Do they use Linux?':",options:["Yes, they do.","Yes, they are.","Yes, they does."],ans:"Yes, they do."}],chunks:[{en:"do you study every day?",pt:"você estuda todos os dias?"},{en:"does she work?",pt:"ela trabalha?"},{en:"yes, I do / no, I don't",pt:"sim / não (respostas curtas)"}],listeningScript:"Do you work from home? Yes, I do. Does your company use Zoom? No, it uses Teams. Does the server work at night? Yes, it always does. Do they have meetings on Fridays?",speakingPrompt:"Pergunte e responda: 'Do you study at night? Yes, I do. Does your friend play games? No, he doesn't.'",lightReading:"Support interviews always start with habit questions: do you deploy daily? does your team review code? Present Simple drives daily rituals.",journalPrompt:"Today is Day 26. I can make questions about habits.",tip:"DICA DE LISTENING: respostas curtas (Yes, I do / No, I don't) aparecem em TODA conversa em inglês. Treine-as em voz alta com o áudio 3x — elas dão tempo de pensar enquanto conversa."},27:{dayName:"Dia 27 — Sábado",title:"Rotina & Present Simple + TESTE DE SÁBADO 4",focus:"Revisar Present Simple completo e realizar o teste semanal.",vocab:[{en:"Routine",pt:"Rotina"},{en:"Habit",pt:"Hábito"},{en:"Daily",pt:"Diário"},{en:"Weekly",pt:"Semanal"},{en:"Monthly",pt:"Mensal"},{en:"Every day",pt:"Todos os dias"},{en:"Today",pt:"Hoje"},{en:"Tomorrow",pt:"Amanhã"},{en:"Yesterday",pt:"Ontem"},{en:"Now",pt:"Agora"}],grammar:{title:"Resumo da Semana 4: Present Simple",rule:"Afirmativa (I work / she works), negativa (I don't work / she doesn't work), pergunta (Do you work? / Does she work?).",table:[{form:"Afirmativa",example:"She works every morning. They study daily.",pt:"Ela trabalha toda manhã. Eles estudam diariamente."},{form:"Negativa",example:"He doesn't wake up late. We don't eat fast food.",pt:"Ele não acorda tarde. Nós não comemos fast food."},{form:"Pergunta",example:"Do you exercise weekly? Does it work well?",pt:"Você se exercita semanalmente? Funciona bem?"}]},reading:{title:"My Week",text:"Every day I wake up at six thirty. In the morning I study English and work. At lunch I read the news. In the afternoon I write code. Does my routine change on weekends? Yes, it does. On weekends I don't work. I rest and play games.",translation:"Todos os dias eu acordo às seis e meia. De manhã estudo inglês e trabalho. No almoço leio as notícias. À tarde escrevo código. Minha rotina muda nos fins de semana? Sim. Nos fins de semana eu não trabalho. Eu descanso e jogo games."},quiz:[{q:"Complete: 'Every day I ___ up at six thirty.'",options:["wake","wakes","waking"],ans:"wake"},{q:"Complete: 'My routine ___ on weekends?'",options:["Do...change","Does...change","Does...changes"],ans:"Does...change"},{q:"'On weekends I don't work' significa:",options:["não trabalho","não descanso","trabalho sempre"],ans:"não trabalho"}],chunks:[{en:"every day I wake up",pt:"todos os dias eu acordo"},{en:"my routine changes",pt:"minha rotina muda"},{en:"on weekends I rest",pt:"nos fins de semana eu descanso"}],listeningScript:"My week is busy. I wake up at six. Do I work on Saturdays? No, I don't. Does my team work on Sundays? No, it doesn't. We all rest on the weekend.",speakingPrompt:"Resuma sua semana: 'Every day I wake up at seven. I study. On weekends I don't work. I rest.'",lightReading:"Habit-tracking apps work like Present Simple: they log what you do daily, weekly, monthly — frequency data is habit language.",journalPrompt:"Today is Day 27. I completed my fourth Saturday Test!",tip:"DICA DE MEMÓRIA: crie 3 frases da SUA vida real com o Present Simple e grave-as no áudio. Sua rotina é o melhor banco de exemplos que existe."},28:{dayName:"Dia 28 — Domingo",title:"Revisão Geral da Semana 4 & Imersão Leve",focus:"Consolidar o Present Simple com leitura, escuta e revisão.",vocab:[{en:"Family",pt:"Família"},{en:"Mother",pt:"Mãe"},{en:"Father",pt:"Pai"},{en:"Parents",pt:"Pais"},{en:"Grandmother",pt:"Avó"},{en:"Grandfather",pt:"Avô"},{en:"Uncle",pt:"Tio"},{en:"Aunt",pt:"Tia"},{en:"Cousin",pt:"Primo(a)"},{en:"Nephew",pt:"Sobrinho"}],grammar:{title:"Checkpoint 28 — Rotina em Inglês",rule:"Você já descreve FAMÍLIA e ROTINA completa: afirmativa, negativa e interrogativa. Isso é 30% do nível A1 dominado.",table:[{form:"Família",example:"My mother works at a bank. My father is retired.",pt:"Minha mãe trabalha num banco. Meu pai é aposentado."},{form:"Rotina",example:"My parents wake up early. They don't sleep late.",pt:"Meus pais acordam cedo. Eles não dormem até tarde."},{form:"Pergunta",example:"Does your family live near here? Yes, it does.",pt:"Sua família mora perto daqui? Sim."}]},reading:{title:"My Family",text:"My family is small. My mother works at a hospital. My father is a teacher, but he doesn't work now. My grandmother lives with us. My uncle lives in another country. Every Sunday we talk online. The whole family loves technology.",translation:"Minha família é pequena. Minha mãe trabalha num hospital. Meu pai é professor, mas não trabalha agora. Minha avó mora conosco. Meu tio mora em outro país. Todo domingo conversamos online. A família inteira adora tecnologia."},quiz:[{q:"'My mother works at a hospital' — verbo correto porque:",options:["mother = he/she/it","mother = plural","ação no passado"],ans:"mother = he/she/it"},{q:"Complete: 'He ___ work now.'",options:["don't","doesn't","isn't"],ans:"doesn't"},{q:"'My grandmother lives with us' significa:",options:["mora conosco","trabalha conosco","não mora aqui"],ans:"mora conosco"}],chunks:[{en:"my family is small",pt:"minha família é pequena"},{en:"we talk online",pt:"conversamos online"},{en:"the whole family",pt:"a família inteira"}],listeningScript:"I love my family. My mother works at a hospital. My father doesn't work now. My grandmother lives with us. Every Sunday we talk online together.",speakingPrompt:"Fale sobre sua família: 'My mother is a [profissão]. My father works at [lugar]. We live in [cidade].'",lightReading:"Video calls keep families connected across countries — the meeting app converts distance into a weekly ritual.",journalPrompt:"Today is Day 28. I finished Week 4. My routine stories are complete.",tip:"DICA DE APRENDIZADO: narrativas curtas (30 segundos) sobre sua rotina, gravadas 1x por semana, mostram seu progresso real. Você perceberá a fluência subindo aos poucos."},29:{dayName:"Dia 29 — Segunda-feira",title:"Perguntas com W-Words (What, Where, When, Why, Who)",focus:"Formar perguntas abertas com as palavras interrogativas essenciais.",vocab:[{en:"What",pt:"O quê / Qual"},{en:"Where",pt:"Onde"},{en:"When",pt:"Quando"},{en:"Why",pt:"Por quê"},{en:"Who",pt:"Quem"},{en:"How",pt:"Como"},{en:"Information",pt:"Informação"},{en:"Reason",pt:"Motivo"},{en:"Meeting",pt:"Reunião"},{en:"Schedule",pt:"Agenda / Cronograma"}],grammar:{title:"W-Questions",rule:"WH/hOW + verbo auxiliar do Present Simple (do/does) + sujeito + verbo: What do you study? Onde = Where, Quando = When, Por quê = Why, Quem = Who, Como = How.",table:[{form:"WHAT",example:"What do you study? I study computer science.",pt:"O que você estuda? Estudo ciência da computação."},{form:"WHERE / WHEN",example:"Where do you work? When does the meeting start?",pt:"Onde você trabalha? Quando começa a reunião?"},{form:"WHY / WHO",example:"Why do you learn English? Who is your teacher?",pt:"Por que você aprende inglês? Quem é seu professor?"}],foundation:{title:"A pergunta tem duas partes",explanation:"Perguntas abertas usam uma palavra para pedir a informação e depois usam a mesma estrutura de pergunta que você já aprendeu. A exceção comum é WHO quando ele próprio é a pessoa que faz a ação.",steps:["Informação + ação: What do you study? / Where does she work?","Com To Be: Where are you? / Who is she?","WHO como sujeito: Who works here? (não precisa de do/does)."],warning:"Não diga 'Where you work?' no inglês padrão. Para ações/hábitos, use DO/DOES."}},reading:{title:"The New Project",text:"What is the new project about? It is about artificial intelligence. Where does the team work? They work in the new office. When does the project start? It starts in March. Who leads the project? Ana leads it. Why do we need more people? Because the schedule is tight.",translation:"Sobre o que é o novo projeto? É sobre inteligência artificial. Onde a equipe trabalha? Eles trabalham no novo escritório. Quando o projeto começa? Começa em março. Quem lidera o projeto? Ana lidera. Por que precisamos de mais pessoas? Porque o cronograma está apertado."},quiz:[{q:"Complete: '___ do you study? — Computer science.'",options:["Where","What","When"],ans:"What"},{q:"Complete: '___ does the meeting start? — At 10.'",options:["When","Who","Why"],ans:"When"},{q:"Complete: '___ is your teacher? — Mrs. Silva.'",options:["Where","Who","What"],ans:"Who"}],chunks:[{en:"what do you study?",pt:"o que você estuda?"},{en:"when does it start?",pt:"quando começa?"},{en:"who leads the project?",pt:"quem lidera o projeto?"}],listeningScript:"What is your job? I am a developer. Where do you work? I work from home. When do you start? At nine. Why do you like it? Because I love coding. Who is your manager? Mark.",speakingPrompt:"Pergunte e responda: 'What do you study? Where do you live? When do you study? Why?'",lightReading:"Interview questions are 90% W-questions: what, where, when, why, who — master them and you master job interviews.",journalPrompt:"Today is Day 29. I learned all the W-question words.",tip:"DICA DE ESCRITA: ao aprender uma nova estrutura, escreva uma pergunta e a resposta de imediato. Pergunta + resposta = o par natural que você usará de verdade."},30:{dayName:"Dia 30 — Terça-feira",title:"How Much / How Many / How Often",focus:"Perguntar quantidade e frequência com how much, how many, how often.",vocab:[{en:"How much",pt:"Quanto (incontável)"},{en:"How many",pt:"Quantos (contável)"},{en:"How often",pt:"Com que frequência"},{en:"Money",pt:"Dinheiro"},{en:"Water",pt:"Água"},{en:"Sugar",pt:"Açúcar"},{en:"Bottle",pt:"Garrafa"},{en:"Glass",pt:"Copo"},{en:"Cup",pt:"Xícara"},{en:"Piece",pt:"Pedaço"}],grammar:{title:"How Much / How Many / How Often",rule:"HOW MUCH + incontáveis (money, water): How much money do you have? HOW MANY + contáveis (bottles, users): How many users are there? HOW OFTEN + rotina: How often do you study?",table:[{form:"How much + incontável",example:"How much water do you drink?",pt:"Quanta água você bebe?"},{form:"How many + contável",example:"How many users does the app have?",pt:"Quantos usuários o app tem?"},{form:"How often + hábito",example:"How often do you check your email?",pt:"Com que frequência você checa seu e-mail?"}]},reading:{title:"The New App",text:"How many users does the new app have? It has fifty thousand users. How much space do we need for the database? We need about one hundred gigabytes. How often do we update the app? We update it weekly. How much does it cost? It is free.",translation:"Quantos usuários o novo app tem? Tem cinquenta mil usuários. Quanto espaço precisamos para o banco de dados? Precisamos de cerca de cem gigabytes. Com que frequência atualizamos o app? Atualizamos semanalmente. Quanto custa? É gratuito."},quiz:[{q:"Complete: '___ users does the app have?'",options:["How much","How many","How often"],ans:"How many"},{q:"Complete: '___ water do you drink?'",options:["How much","How many","How"],ans:"How much"},{q:"Complete: '___ do you update the app? — Weekly.'",options:["How often","How much","How many"],ans:"How often"}],chunks:[{en:"how many users?",pt:"quantos usuários?"},{en:"how much space?",pt:"quanto espaço?"},{en:"we update it weekly",pt:"atualizamos semanalmente"}],listeningScript:"How many people are on the call? Forty. How much time do we have? Thirty minutes. How often does the server fail? Rarely. How much memory does the app use? Not much.",speakingPrompt:"Pergunte: 'How many apps do you have? How much time do you study? How often do you practice?'",lightReading:"Capacity planning asks exactly these questions: how many requests, how much memory, how often backups run.",journalPrompt:"Today is Day 30. I learned how much, how many and how often.",tip:"DICA DE MEMÓRIA: MUCH = dinheiro/água (massa, sem plural); MANY = itens que dá para contar (users, apps). Teste mental rápido: 'dá para contar?' Sim = many. Não = much."},31:{dayName:"Dia 31 — Quarta-feira",title:"Present Continuous — Afirmativa & Negativa",focus:"Descrever ações acontecendo AGORA com be + verbo + ing.",vocab:[{en:"Now",pt:"Agora"},{en:"Right now",pt:"Neste momento"},{en:"At the moment",pt:"No momento"},{en:"Currently",pt:"Atualmente"},{en:"Working",pt:"Trabalhando"},{en:"Studying",pt:"Estudando"},{en:"Reading",pt:"Lendo"},{en:"Writing",pt:"Escrevendo"},{en:"Watching",pt:"Assistindo"},{en:"Cooking",pt:"Cozinhando"}],grammar:{title:"Present Continuous",rule:"AM/IS/ARE + verbo(-ING): I am studying, She is working, They are reading. Negativa: am not / isn't / aren't + -ing.",table:[{form:"Afirmativa",example:"I am studying English right now.",pt:"Estou estudando inglês agora."},{form:"Negativa",example:"She isn't working today. They aren't playing.",pt:"Ela não está trabalhando hoje. Eles não estão jogando."},{form:"Regra do -ing",example:"write -> writing, run -> running, study -> studying",pt:"escrever, correr, estudar"}],foundation:{title:"Uma ação em andamento precisa de duas peças",explanation:"O Present Continuous não é só verbo com -ing. Ele sempre precisa de uma forma de To Be + verbo com -ing. To Be mostra a pessoa; -ing mostra que a ação está acontecendo/temporária.",steps:["I am studying now.","She is working today.","They are not playing."],warning:"Não diga 'I studying' ou 'I am study'. Use sempre AM/IS/ARE + verbo-ING."}},reading:{title:"What Is Happening Now?",text:"Right now, my brother is working at home. My sister is cooking lunch. I am studying English at the moment. The team is having a video call. Nobody is playing games. We are all busy now.",translation:"Neste momento, meu irmão está trabalhando em casa. Minha irmã está cozinhando o almoço. Eu estou estudando inglês no momento. A equipe está numa videochamada. Ninguém está jogando games. Estamos todos ocupados agora."},quiz:[{q:"Complete: 'I ___ studying now.'",options:["am","is","are"],ans:"am"},{q:"Complete: 'She ___ working today.' (negativa)",options:["isn't","don't","aren't"],ans:"isn't"},{q:"Complete: 'write -> ___'",options:["writing","writeing","writting"],ans:"writing"}],chunks:[{en:"I am studying right now",pt:"estou estudando agora"},{en:"she isn't working today",pt:"ela não está trabalhando hoje"},{en:"we are all busy",pt:"estamos todos ocupados"}],listeningScript:"What are you doing right now? I am working. My colleague is writing a report. The servers are processing data. The team is having a meeting at the moment.",speakingPrompt:"Conte o que acontece agora ao seu redor: 'Right now I am [verbo+ing]. My brother is sleeping. The cat is eating.'",lightReading:"Status messages use the continuous: 'server is running', 'build is compiling', 'processing...' — the language of real-time systems.",journalPrompt:"Today is Day 31. I learned the Present Continuous.",tip:"DICA DE LEITURA: o -ING no final = ação em andamento ('comando', 'processando'). Ao ler 'is running', veja como 'está rodando'. PORTUGUÊS usa 'está + ndo'; inglês usa 'is + ing' — mesma lógica!"},32:{dayName:"Dia 32 — Quinta-feira",title:"Present Continuous — Perguntas & Spelling do -ing",focus:"Perguntar sobre ações em andamento e soletrar o -ing corretamente.",vocab:[{en:"Answering",pt:"Respondendo"},{en:"Asking",pt:"Perguntando"},{en:"Calling",pt:"Ligando / Chamando"},{en:"Sending",pt:"Enviando"},{en:"Receiving",pt:"Recebendo"},{en:"Waiting",pt:"Esperando"},{en:"Arriving",pt:"Chegando"},{en:"Leaving",pt:"Saindo"},{en:"Fixing",pt:"Consertando"},{en:"Testing",pt:"Testando"}],grammar:{title:"Perguntas no Continuous + Spelling",rule:"AM/IS/ARE + sujeito + -ing: Is she working? / What are you doing? Spelling: termina em e -> tira e (make -> making); consoante+vogal+consoante -> dobra (run -> running).",table:[{form:"Pergunta",example:"What are you doing? Is the server working?",pt:"O que você está fazendo? O servidor está funcionando?"},{form:"Tira o E",example:"make -> making, write -> writing",pt:"fazer, escrever"},{form:"Dobra consoante",example:"run -> running, sit -> sitting",pt:"correr, sentar"}],foundation:{title:"Pergunta no Continuous: mova só o To Be",explanation:"Você já sabe a frase: You are studying. Para perguntar, mova ARE para a frente: Are you studying? O verbo com -ing continua depois da pessoa.",steps:["Afirmação: She is working.","Pergunta: Is she working?","Com informação: What are you doing?"],warning:"Não use DO/DOES com -ing: 'Do you studying?' está errado. Para ações agora, use AM/IS/ARE."}},reading:{title:"Tech Support Call",text:"Hello, what are you doing? I am fixing your computer. Why is the screen dark? Because the cable isn't connected. Are you sending the update now? Yes, I am sending it. How long is it taking? It is taking a few minutes. Thanks, you are very helpful!",translation:"Olá, o que você está fazendo? Estou consertando seu computador. Por que a tela está escura? Porque o cabo não está conectado. Você está enviando a atualização agora? Sim, estou enviando. Quanto tempo está levando? Está levando alguns minutos. Obrigado, você é muito útil!"},quiz:[{q:"Pergunta correta:",options:["What are you doing?","What you are doing?","What is you doing?"],ans:"What are you doing?"},{q:"Complete: 'make -> ___'",options:["making","makeing","macking"],ans:"making"},{q:"Complete: 'run -> ___'",options:["running","runing","runny"],ans:"running"}],chunks:[{en:"what are you doing?",pt:"o que você está fazendo?"},{en:"how long is it taking?",pt:"quanto tempo está levando?"},{en:"you are very helpful",pt:"você é muito útil"}],listeningScript:"Are you working from home today? Yes, I am working here. What is your team doing? They are testing the new version. Is everything running? Yes, it is running smoothly.",speakingPrompt:"Pergunte e responda: 'What are you doing? I am studying. Is your friend studying? No, she is sleeping.'",lightReading:"Spelling rules in English (-ing) are like naming conventions in code — small rules that prevent big syntax errors.",journalPrompt:"Today is Day 32. I learned continuous questions and -ing spelling.",tip:"DICA DE ESCRITA: 'What are you doing?' é a frase de abertura de TODA conversa natural. Domine essa pergunta + 3 respostas (-ing) e você abrirá qualquer diálogo."},33:{dayName:"Dia 33 — Sexta-feira",title:"Present Simple vs Present Continuous",focus:"Diferenciar hábito (simple) de ação momentânea (continuous).",vocab:[{en:"Generally",pt:"Geralmente"},{en:"At this moment",pt:"Neste momento"},{en:"These days",pt:"Atualmente / Esses dias"},{en:"Lately",pt:"Ultimamente"},{en:"Permanent",pt:"Permanente"},{en:"Temporary",pt:"Temporário"},{en:"Situation",pt:"Situação"},{en:"Action",pt:"Ação"},{en:"Habit",pt:"Hábito"},{en:"State",pt:"Estado"}],grammar:{title:"Simple vs Continuous",rule:"SIMPLE = hábitos e fatos fixos (I work at a bank). CONTINUOUS = agora, temporário, em progresso (I am working on a task right now).",table:[{form:"Hábito (Simple)",example:"I work from 9 to 6 every day.",pt:"Trabalho das 9 às 6 todos os dias."},{form:"Agora (Continuous)",example:"Right now, I am working on a report.",pt:"Agora estou trabalhando num relatório."},{form:"Contraste",example:"She usually walks, but today she is driving.",pt:"Ela geralmente caminha, mas hoje está dirigindo."}],foundation:{title:"Pergunta-chave: hábito ou agora?",explanation:"Antes de escolher o tempo verbal, pergunte: isso acontece regularmente ou está acontecendo neste momento/temporariamente? A resposta define a estrutura.",steps:["Hábito: I study English every day. (verbo base)","Agora: I am studying English now. (am + -ing)","Contraste: She works from home, but today she is working at the office."],warning:"Palavras como every day, usually e always tendem a pedir Simple; now, right now e at the moment tendem a pedir Continuous."}},reading:{title:"Always and Right Now",text:"I work at a software company. Every morning I check emails. Right now, I am checking the system logs. My coworker normally fixes bugs, but today she is planning the new release. These days, everyone is working on the same project. It is exciting!",translation:"Trabalho numa empresa de software. Toda manhã checo os e-mails. Agora, estou checando os logs do sistema. Minha colega normalmente corrige bugs, mas hoje ela está planejando o novo lançamento. Ultimamente, todos estão trabalhando no mesmo projeto. É emocionante!"},quiz:[{q:"Hábito: escolha certo:",options:["I am working every day","I work every day","I working every day"],ans:"I work every day"},{q:"Ação agora:",options:["I check logs right now","I am checking logs right now","I checks logs now"],ans:"I am checking logs right now"},{q:"Complete: 'She normally ___ bugs.'",options:["fix","fixes","is fixing"],ans:"fixes"}],chunks:[{en:"normally I fix bugs",pt:"normalmente eu corrijo bugs"},{en:"right now I am planning",pt:"agora estou planejando"},{en:"these days we are working together",pt:"ultimamente trabalhamos juntos"}],listeningScript:"I normally work in the office. But this week I am working from home. My colleague usually arrives at eight. Today he is arriving late. Things change, and English describes both.",speakingPrompt:"Contraste: 'I usually study at night. Right now I am studying. She normally plays games. Today she is studying.'",lightReading:"Monitoring dashboards mix both: what normally happens (baseline) vs what is happening now (alerts) — simple for state, continuous for change.",journalPrompt:"Today is Day 33. I can contrast habits and current actions.",tip:"DICA DE APRENDIZADO: palavras-chave entregam o tempo: SIMPLE = every day, usually, always, on Mondays. CONTINUOUS = now, right now, at the moment, today. Ao ler, procure essas pistas."},34:{dayName:"Dia 34 — Sábado",title:"Present Perfect no Presente & TESTE DE SÁBADO 5",focus:"Revisar perguntas e verbos no presente e realizar o teste semanal.",vocab:[{en:"Question word",pt:"Palavra interrogativa"},{en:"Frequency",pt:"Frequência"},{en:"Progress",pt:"Progresso"},{en:"Improvement",pt:"Melhora"},{en:"Result",pt:"Resultado"},{en:"Success",pt:"Sucesso"},{en:"Effort",pt:"Esforço"},{en:"Attention",pt:"Atenção"},{en:"Detail",pt:"Detalhe"},{en:"Goal",pt:"Meta"}],grammar:{title:"Resumo da Semana 5",rule:"Perguntas W (what/where/when/why/who), how much/many/often, Present Continuous (be + -ing) e diferença simple vs continuous.",table:[{form:"Perguntas",example:"What are you doing? Where does she work?",pt:"O que você está fazendo? Onde ela trabalha?"},{form:"Continuo",example:"I am writing code right now.",pt:"Estou escrevendo código agora."},{form:"Hábito",example:"I usually write code in the morning.",pt:"Costumo escrever código de manhã."}]},reading:{title:"My Improvement",text:"Why am I improving? Because I study with attention every day. How often do I practice listening? Every single day. What am I doing right now? I am reviewing week five. How many hours do I study? About four hours. My goal is clear and my effort is real.",translation:"Por que estou melhorando? Porque estudo com atenção todos os dias. Com que frequência pratico listening? Todos os dias. O que estou fazendo agora? Revisando a semana cinco. Quantas horas estudo? Cerca de quatro. Minha meta é clara e meu esforço é real."},quiz:[{q:"Complete: '___ are you doing? — I am reviewing.'",options:["What","Where","When"],ans:"What"},{q:"Complete: 'How ___ do you practice? — Daily.'",options:["much","often","many"],ans:"often"},{q:"Complete: 'I usually ___ in the morning.'",options:["study","am studying","studies"],ans:"study"}],chunks:[{en:"my goal is clear",pt:"minha meta é clara"},{en:"my effort is real",pt:"meu esforço é real"},{en:"I am reviewing week five",pt:"estou revisando a semana cinco"}],listeningScript:"How are you today? I am great. What are you doing? I am preparing the weekly test. How often do you review? Every Saturday. That is a great habit!",speakingPrompt:"Autoavaliação: 'This week I studied questions and the continuous. I am improving every day.'",lightReading:"Self-assessment is like a code review: you check progress, find gaps, and fix them before the next sprint.",journalPrompt:"Today is Day 34. I completed my fifth Saturday Test!",tip:"DICA DE LEITURA: crie o hábito de perguntar ao final de cada texto: 'What? Where? When? Why? Who?' Se você responder as 5, entendeu o texto. Faça isso com o texto de hoje."},35:{dayName:"Dia 35 — Domingo",title:"Revisão Geral da Semana 5 & Imersão Leve",focus:"Consolidar as 5 semanas e celebrar o marco de 1/5 do curso.",vocab:[{en:"Milestone",pt:"Marco"},{en:"Journey",pt:"Jornada"},{en:"Beginning",pt:"Começo"},{en:"Middle",pt:"Meio"},{en:"End",pt:"Fim"},{en:"Future",pt:"Futuro"},{en:"Past",pt:"Passado"},{en:"Present",pt:"Presente"},{en:"Now",pt:"Agora"},{en:"Soon",pt:"Em breve"}],grammar:{title:"Checkpoint 35 — Um mês completo!",rule:"Você domina To Be, artigos, plurais, demonstrativos, possessivos, preposições, there is/are, have/has, Present Simple completo e Present Continuous. Isso é mais da metade do conteúdo A1.",table:[{form:"Descrever",example:"There is a laptop on the desk. It is mine.",pt:"Há um notebook na mesa. É meu."},{form:"Rotina",example:"I wake up early. I don't watch TV at night.",pt:"Acordo cedo. Não assisto TV à noite."},{form:"Agora",example:"Right now I am reviewing everything.",pt:"Agora estou revisando tudo."}]},reading:{title:"A Month of English",text:"I am at the end of my first month. My journey is just beginning. In the past I didn't understand anything. Now I read short texts and understand daily conversations. Soon I will learn the past and the future. My middle goal is to reach level A2 with confidence.",translation:"Estou no fim do meu primeiro mês. Minha jornada está apenas começando. No passado eu não entendia nada. Agora leio textos curtos e entendo conversas diárias. Em breve aprenderei o passado e o futuro. Minha meta intermediária é chegar ao nível A2 com confiança."},quiz:[{q:"'In the past I didn't understand' — o texto fala de:",options:["hábito atual","ação passada","plano futuro"],ans:"ação passada"},{q:"Complete: 'I ___ read short texts now.' (correto)",options:["can","cans","am can"],ans:"can"},{q:"'My journey is just beginning' significa:",options:["minha jornada começou agora","minha jornada acabou","estou no meio"],ans:"minha jornada começou agora"}],chunks:[{en:"I don't understand anything",pt:"não entendo nada"},{en:"I can read short texts",pt:"consigo ler textos curtos"},{en:"my milestone is clear",pt:"meu marco está claro"}],listeningScript:"Congratulations! You finished the first month of your English journey. Your foundation is growing strong. Keep the same routine. The next months will bring the past and the future tenses!",speakingPrompt:"Celebre seu marco: 'I finished one month. I can read short texts. I am proud of myself. The journey continues!'",lightReading:"Milestones in language learning are like releases in software: month one is your first stable build — small, tested, and ready to grow.",journalPrompt:"Today is Day 35. One month complete! I am proud and motivated.",tip:"DICA DE APRENDIZADO: recompense marcos de forma que preserivem o hábito. Competir consigo mesmo (XP, sequências, tempo total) mantém a motivação — consulte seu Painel Diário."}},a=[{id:1,title:"Semana 1 — Fundação Absoluta",daysRange:"Dias 1 a 7",subtitle:"Alphabet, Pronouns, To Be & Primeiras Frases",badgeClass:"badge-emerald",grammar:["Alphabet & sons dos sons das letras","Personal Pronouns (I, You, He, She, It, We, They)","Verb To Be (afirmativa, negativa, perguntas, respostas curtas)","Contrações (I'm, You're, Isn't, Aren't)"],vocab:"100+ palavras essenciais: apresentação, objetos, hardware básico",reading:"Textos de 30-50 palavras sobre apresentação e ambiente de trabalho",listening:"Áudios curtos A1 de apresentação e TI com o Método dos 5 Passos",speaking:"Monólogo de 1 minuto: 'My name is... I am from... I live in...'",techBridge:"Cognatos tech: computer, internet, program, system, file, code",saturday:{recall:[["I am a student","Eu sou um estudante"],["Are you ready?","Você está pronto?"],["He isn't busy","Ele não está ocupado"],["This is my laptop","Este é meu notebook"],["an application","um aplicativo"],["The database is online","O banco de dados está online"],["These are my files","Estes são meus arquivos"],["That is an old server","Aquele é um servidor antigo"],["Our team is great","Nossa equipe é ótima"],["Her app is live","O app dela está no ar"],["Week 1 is complete","A Semana 1 está completa"],["I live in Brazil","Eu moro no Brasil"]],reading:{title:"Welcome to Our Company",text:"Welcome to our company. This is our office. My name is Mark and I am the manager. There are many people here. The developers are in the big room. The computers are new and fast. Our team is small, but our projects are great. Are you ready to work with us? Yes, I am.",questions:["What is Mark's job?","Where are the developers?","Is the team big or small?","Are the computers new?","Is the office big?"]},listening:"Welcome to Week One Test. Listen: 'Hello, I am Ana. I am a developer. This is my computer. It is fast. These are my files. They are organized. Are you ready? Yes, I am great.'",speaking:"Final da Semana 1: grave 2 minutos falando: 'My name is... I am a student. I live in Brazil. This is my computer...'"}},{id:2,title:"Semana 2 — Artigos, Plurais & Demonstrativos",daysRange:"Dias 8 a 14",subtitle:"A/An/The, Plurals e This/That/These/Those",badgeClass:"badge-blue",grammar:["Articles A, An, The (regra do som e do específico)","Zero article (idiomas, refeições, plurais gerais)","Plurals regulares (-s, -es, -ies) e irregulares (man/men)","Demonstrativos This, That, These, Those + one/ones"],vocab:"Objetos, hardware, apps, arquivos, cidades e pessoas",reading:"Textos de 40-70 palavras sobre e-mail, escritório e aplicativos",listening:"Áudios reais A1 sobre o dia a dia digital",speaking:"Descrever 5 objetos ao redor usando artigos e demonstrativos",techBridge:"Vocabulário: application, user, error, algorithm, database, software, hardware",saturday:{recall:[["an hour","uma hora"],["a university","uma universidade"],["boxes","caixas"],["cities","cidades"],["men / women","homens / mulheres"],["children","crianças"],["people","pessoas"],["this app is for messages","este app é para mensagens"],["that window lets in light","aquela janela deixa entrar luz"],["an internet connection","uma conexão com a internet"],["the developers' code","o código dos desenvolvedores"],["many users","muitos usuários"]],reading:{title:"A Small Company",text:"There is a small company in our city. The company makes applications for phones. The users like the apps because they are fast. An engineer works there. His name is Paulo. He fixes errors every day. The women in marketing manage the website. The children of the employees visit on Fridays. There are many boxes of old equipment in the storage room.",questions:["What does the company make?","Why do users like the apps?","What does Paulo do?","Who manages the website?","Where are the old boxes?"]},listening:"Listen: 'This is our office. These computers are new. Those printers are old. There are many boxes in the storage room. The engineers fix errors every day. People love our apps because they are fast.'",speaking:"Grave 2 minutos: 'This is my phone. These are my apps. That is the door. There are many people in my city...'"}},{id:3,title:"Semana 3 — Possessivos & Preposições de Lugar",daysRange:"Dias 15 a 21",subtitle:"My/Mine, Genitive 's e in/on/at/under/next to",badgeClass:"badge-emerald",grammar:["Possessive adjectives (my, your, his, her, its, our, their)","Possessive pronouns (mine, yours, hers, ours, theirs)","Genitive case ('s e s')","Prepositions of place (in, on, at, under, next to, between, behind, in front of, above)"],vocab:"Senhas, contas, objetos pessoais, lugares da cidade e do escritório",reading:"Textos de 50-80 palavras sobre posse e localização",listening:"Diálogos sobre 'where is...' e 'whose is...'",speaking:"Descrever onde as coisas estão na sua mesa de trabalho",techBridge:"Vocabulário: password, account, profile, server, router, data center, key",saturday:{recall:[["this laptop is mine","este notebook é meu"],["it belongs to him","pertence a ele"],["my friend's laptop","o notebook do meu amigo"],["the developers' code","o código dos desenvolvedores"],["in front of the monitor","em frente ao monitor"],["between the desk and the wall","entre a mesa e a parede"],["above the screen","acima da tela"],["next to the bank","ao lado do banco"],["my own account","minha própria conta"],["protect our data","proteger nossos dados"],["on the third floor","no terceiro andar"],["in the city center","no centro da cidade"]],reading:{title:"Finding the New Office",text:"Ana's office is in the city center. It is on Main Street, next to the bank. The metro station is in front of the building. The park is behind the hospital. Ana's desk is in the corner of the third floor. Her computer is on the desk. The router is under the table. Between the desk and the wall, there is a cabinet. It is a nice office.",questions:["Where is Ana's office?","What is in front of the building?","Where is Ana's desk?","Where is the router?","What is between the desk and the wall?"]},listening:"Listen: 'Whose laptop is this? It is mine. Where is the router? It is under the table. Where is the manager? He is in the office on the third floor. The printer is next to the window. Everything is in the right place.'",speaking:"Grave 2 minutos descrevendo sua mesa: 'This is my desk. My laptop is on the table. The charger is next to the keyboard...'"}},{id:4,title:"Semana 4 — There Is/Are, Have/Has & Present Simple",daysRange:"Dias 22 a 28",subtitle:"Existir, Ter e Rotina no Presente",badgeClass:"badge-amber",grammar:["There is / There are (afirmativa, negativa, perguntas)","Have / Has (posse e características)","Present Simple afirmativo com -s na 3ª pessoa","Negativas (don't/doesn't) e perguntas (do/does) + respostas curtas"],vocab:"Rotina, família, hábitos, objetos do escritório (300-500 palavras acumuladas)",reading:"Textos de 50-80 palavras sobre rotina e família",listening:"Escuta com foco na terminação -s da 3ª pessoa",speaking:"Falar sobre sua rotina matinal durante 2 minutos",techBridge:"Frases tech: 'There is a bug', 'The server has data', 'I use Linux'",saturday:{recall:[["there is a printer","há uma impressora"],["there are two monitors","há dois monitores"],["is there a lamp?","há um abajur?"],["I have an idea","tenho uma ideia"],["she has a solution","ela tem uma solução"],["do you have any questions?","você tem alguma pergunta?"],["I wake up at seven","acordo às sete"],["he starts at nine","ele começa às nove"],["she doesn't speak English","ela não fala inglês"],["we don't work on Sundays","não trabalhamos aos domingos"],["does she work?","ela trabalha?"],["yes, I do / no, I don't","sim / não (respostas curtas)"]],reading:{title:"My Brother's Routine",text:"My brother works at a technology company. He wakes up at six forty-five. His routine is always the same. He doesn't take breakfast at home. He drinks coffee at the office. Does he work on weekends? No, he doesn't. He watches football on Saturdays. There is a big screen in his house. My sister doesn't live with us. She lives in another city, but she calls us every Sunday. We have a happy family.",questions:["What time does the brother wake up?","Does he take breakfast at home?","Does he work on weekends?","What does he do on Saturdays?","Where does the sister live?"]},listening:"Listen: 'This is my daily routine. I wake up at six. I don't take breakfast. At work, there are three monitors on my desk. Does my routine change on weekends? Yes, it does. On Saturdays, there is no work. I rest and play games with my family.'",speaking:"Grave sua rotina matinal: 'I wake up at... I don't... There is/There are... Does my routine change? Yes, it does...'"}},{id:5,title:"Semana 5 — Perguntas & Present Continuous",daysRange:"Dias 29 a 35",subtitle:"W-Questions, How Much/Many/Often e Be + -ing",badgeClass:"badge-blue",grammar:["Question words (what, who, where, when, why, how)","How much / How many / How often","Present Continuous (affirmativa, negativa, perguntas)","Present Simple vs Present Continuous"],vocab:"Ações em progresso, tempo, frequência e projetos",reading:"Textos de 60-90 palavras sobre projetos e rotina em andamento",listening:"60 min/dia de escuta ativa (30 min intensivo + 30 min shadowing)",speaking:"Narrar em tempo real o que você está fazendo",techBridge:"Expressões: 'The system is running', 'I am debugging', 'Data is loading'",saturday:{recall:[["what do you study?","o que você estuda?"],["when does it start?","quando começa?"],["who leads the project?","quem lidera o projeto?"],["how many users?","quantos usuários?"],["how much space?","quanto espaço?"],["how often do you practice?","com que frequência você pratica?"],["I am studying right now","estou estudando agora"],["she isn't working today","ela não está trabalhando hoje"],["what are you doing?","o que você está fazendo?"],["I work every day","trabalho todos os dias (hábito)"],["these days we are working together","ultimamente trabalhamos juntos"],["my goal is clear","minha meta é clara"]],reading:{title:"The Team at Work",text:"What is the team doing right now? Ana is writing the new feature. Paulo is testing the application. Maria is checking the server logs. Why is everybody so busy? Because the release is on Friday. Normally, they work from nine to six. Today, they are working until eight. How many people are on the team? Twenty people. How much time is left? About two days. The team is focused and motivated.",questions:["What is Ana doing right now?","Why is everybody busy?","What time do they normally work?","How many people are on the team?","How much time is left?"]},listening:"Listen: 'Hello! What are you doing? I am working on a new feature. What is Ana doing? She is writing code. Normally we finish at six, but today we are working until eight. Why? Because the release is on Friday. The system is running well.'",speaking:"Narre em tempo real: 'Right now I am studying English. I am reading. I am listening. Right now I am speaking!'"}}];export{e as d,a as w};
